export const chatWithGemini = async (
  prompt: string,
  history: { role: 'user' | 'model', parts: any[] }[] = [],
  useThinking: boolean = false,
  attachments: string[] = [],
  useSearch: boolean = false
): Promise<string> => {
  return retryWithBackoff(async () => {
    const ai = getAI();
    const model = useThinking ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const config: any = {
      systemInstruction: SPATIAL_SYSTEM_INSTRUCTION
    };

    if (useThinking) {
      config.thinkingConfig = { thinkingBudget: 16384 }; 
    }

    if (useSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const currentParts: any[] = [];
    attachments.forEach(base64 => {
        if (isBase64Image(base64)) {
            const [mimePart, data] = base64.split(',')[1] ? [base64.split(';')[0].split(':')[1], base64.split(',')[1]] : ['image/jpeg', base64];
            currentParts.push({ inlineData: { data, mimeType: mimePart } });
        }
    });
    currentParts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model,
      contents: [...history, { role: 'user', parts: currentParts }],
      config
    });

    return response.text || "No response from Gemini.";
  });
};

export const extractDesignRecipe = async (images: string[], baselineIndex?: number): Promise<string> => {
