        const spatialTxt = getSpatialInstructions(spatial);
        const recipePart = recipeInstruction ? `\n\n[PRIORITY DESIGN RECIPE]: ${recipeInstruction}` : "";
        const fullPrompt = `${prompt}. ${spatialTxt} ${recipePart}. Style: ${styleSuffix}. Creative intensity: ${artisticScale}`;
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{ parts: [{ text: fullPrompt }] }],
            config: {
                imageConfig: {
                    aspectRatio: normalizeAspectRatio(ratio)
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("No image data generated.");
    });
};

export const generateWithReferences = async (prompt: string, refs: {label: string, base64: string}[], ratio: string, styleSuffix: string, artisticScale: number = 1.0, resolution: string = '1K', spatial?: SpatialConfig, recipeInstruction?: string, inferenceConfig?: InferenceSettings): Promise<string> => {
    return retryWithBackoff(async () => {
        await ensureApiKey();
        const ai = getAI();
        const parts: any[] = [];
        refs.forEach(r => {
            const data = r.base64.split(',')[1] || r.base64;
            const mimeType = r.base64.split(';')[0].split(':')[1] || 'image/jpeg';
            parts.push({ inlineData: { data, mimeType } });
            parts.push({ text: `REFERENCE VOLUME [${r.label}]: Analyze this image for strict geometric massing. PRESERVE THE VOLUMETRIC BOUNDARIES.` });
        });

        const spatialTxt = getSpatialInstructions(spatial);
        const recipePart = recipeInstruction ? `\n\n[GLOBAL DESIGN STYLE RECIPE]: ${recipeInstruction}` : "";

        let finalActionPrompt = prompt;
        if (inferenceConfig) {
            finalActionPrompt = getVolumeInferenceInstructions(inferenceConfig.influence, inferenceConfig.prompt, inferenceConfig.subjectType);
        }

        parts.push({ text: `CHARACTER CONSISTENCY COMMAND: Perform a spatial transformation of the reference subject. \nTARGET VIEW: ${spatialTxt}. ${recipePart} \nACTION: ${finalActionPrompt}. \nIMPORTANT: Maintain the exact breed/type/nature of the subject from the reference.` });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: [{ parts }],
            config: {
                imageConfig: {
                    aspectRatio: (normalizeAspectRatio(ratio) as any),
                    imageSize: (resolution as any)
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error(response.text || "No image generated.");
    });
};

