const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const VALID_ASPECT_RATIOS = ['1:1', '3:4', '4:3', '9:16', '16:9'];

const normalizeAspectRatio = (ratio?: string): string => {
  if (!ratio) return '1:1';
  if (VALID_ASPECT_RATIOS.includes(ratio)) return ratio;

  try {
    const [w, h] = ratio.split(':').map(Number);
    if (isNaN(w) || isNaN(h)) return '1:1';

    const numericRatio = w / h;
    const targets = [
        { id: '1:1', val: 1 },
        { id: '4:3', val: 4/3 },
        { id: '3:4', val: 3/4 },
        { id: '16:9', val: 16/9 },
        { id: '9:16', val: 9/16 }
    ];

    return targets.reduce((prev, curr) => 
        Math.abs(curr.val - numericRatio) < Math.abs(prev.val - numericRatio) ? curr : prev
    ).id;
  } catch (e) {
    return '1:1';
  }
};

export const getClosestGeminiRatio = (width: number, height: number): string => {
    const ratio = width / height;
    const targets = [
        { id: '1:1', val: 1 },
        { id: '4:3', val: 4/3 },
        { id: '3:4', val: 3/4 },
        { id: '16:9', val: 16/9 },
        { id: '9:16', val: 9/16 }
    ];
    return targets.reduce((prev, curr) => 
        Math.abs(curr.val - ratio) < Math.abs(prev.val - ratio) ? curr : prev
    ).id;
};

const isBase64Image = (str: string): boolean => {
  return str.startsWith('data:image/') && str.includes(';base64,');
};

const ensureApiKey = async () => {
    // @ts-ignore
    if (typeof window.aistudio !== 'undefined') {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
            // @ts-ignore
            await window.aistudio.openSelectKey();
        }
    }
};

async function retryWithBackoff<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    let errorStr = '';
    if (typeof error === 'string') errorStr = error;
    else if (error.message) errorStr = error.message;

    const nestedError = error.response?.error || error.error || error;
    if (nestedError && typeof nestedError === 'object') {
        errorStr += ' ' + (nestedError.message || JSON.stringify(nestedError));
    }

    errorStr = errorStr.toLowerCase();

    if (errorStr.includes('requested entity was not found')) {
        // @ts-ignore
        if (typeof window.aistudio !== 'undefined') {
            // @ts-ignore
            await window.aistudio.openSelectKey();
        }
    }

    if (errorStr.includes('failed_precondition') || errorStr.includes('location is not supported')) {
        throw error;
    }

    const isRetryable = 
      errorStr.includes('overloaded') || 
      errorStr.includes('unavailable') || 
      errorStr.includes('429') ||
      errorStr.includes('500') ||
      errorStr.includes('503');

    if (isRetryable && retries > 0) {
      await sleep(delay);
      return retryWithBackoff(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSpatialInstructions = (spatial?: SpatialConfig): string => {
    if (!spatial) return "";

    let viewDesc = "";
    const ele = spatial.elevation;
    const azi = spatial.azimuth;

    if (ele > 80) viewDesc += "Absolute direct top-down plan view, industrial layout photography, ";
    else if (ele > 40) viewDesc += "High-angle perspective, bird's eye view of the product, ";
    else if (ele < -15) viewDesc += "Dramatic low-angle hero shot, looking up at the object, cinematic presence, ";
    else viewDesc += "Standard eye-level studio shot, horizontal profile, ";

    const normalizedAzi = ((azi % 360) + 360) % 360;
    if (normalizedAzi > 345 || normalizedAzi < 15) viewDesc += "absolute front view. ";
    else if (normalizedAzi >= 15 && normalizedAzi < 75) viewDesc += "front-right 3/4 profile. ";
    else if (normalizedAzi >= 75 && normalizedAzi < 105) viewDesc += "exact right-side profile. ";
    else if (normalizedAzi >= 105 && normalizedAzi < 165) viewDesc += "rear-right 3/4 profile. ";
    else if (normalizedAzi >= 165 && normalizedAzi < 195) viewDesc += "absolute back view. ";
    else if (normalizedAzi >= 195 && normalizedAzi < 255) viewDesc += "rear-left 3/4 profile. ";
    else if (normalizedAzi >= 255 && normalizedAzi < 285) viewDesc += "exact left-side profile. ";
    else viewDesc += "front-left 3/4 profile. ";

    const distance = spatial.distance || 12;
    const fov = spatial.fov || 45;

    let lensDesc = "";
    if (distance < 6) lensDesc = "Extreme close-up macro photography, narrow depth of field, fill the entire frame with fine details. ";
    else if (distance > 15) lensDesc = "Wide cinematic shot, environmental context, long distance telephoto perspective. ";
    else lensDesc = "Standard medium product framing. ";

    if (fov < 25) lensDesc += "Telephoto compression, 200mm lens look. ";
    else if (fov > 70) lensDesc += "Wide-angle distortion, 14mm immersive architectural lens. ";

    return `SPATIAL MANDATE: Camera Vector {Elevation: ${Math.round(ele)}°, Azimuth: ${Math.round(normalizedAzi)}°}. PHOTOGRAPHIC STYLE: ${viewDesc} ${lensDesc}. Maintain exact geometric foreshortening and 3D volume scaling for this specific viewpoint.`;
};

const getVolumeInferenceInstructions = (influence: number, prompt: string, subjectType: string = 'industrial'): string => {
    const infPct = Math.round(influence * 100);
    let directive = "";

    const isOrganic = subjectType === 'organic' || subjectType === 'character';
    const material = isOrganic ? "fine sculpting clay / organic matter" : "matte polycarbonate / aerospace aluminum";

    if (influence >= 0.9) {
        directive = `VOLUMETRIC FIDELITY: [STRICT]. Act as a Neural Texture Mapper. Maintain 100% of the reference geometry. Do not add functional apertures or protruding details unless they already exist in the source volume. Focus entirely on applying the high-end materials, CMF textures, and studio lighting belonging to the brand DNA of "${prompt}" onto the existing faces of the ${material} base.`;
    } else if (influence >= 0.7) {
        directive = `VOLUMETRIC FIDELITY: [REFINED]. Use the reference as a structural blueprint. You may introduce subtle surface refinements, shut lines (if industrial), or muscular definition (if organic). The overall proportions and silhouette must remain 95% consistent. Interpret the style of "${prompt}" through material transitions and minor functional details.`;
    } else if (influence >= 0.5) {
        directive = `VOLUMETRIC FIDELITY: [HYBRID]. Use the reference as a 'Hard Massing' block. Transform this volume into a functional ${prompt}. You MUST add necessary functional parts (wheels, ducts, eyes, limbs) anchoring them to or sculpting them out of the original silhouette. The core proportions should stay recognizable.`;
    } else if (influence >= 0.3) {
        directive = `VOLUMETRIC FIDELITY: [ABSTRACT]. Extract only the core spatial center of mass and general proportions. Re-imagine the entire design using the aggressive aesthetic DNA of "${prompt}". The reference serves only as a 'ghost' silhouette to guide the general placement of major volumes.`;
    } else {
        directive = `VOLUMETRIC FIDELITY: [MINIMAL]. Only use the general bounding box logic. Focus 90% on the creative design of "${prompt}". The resulting concept should be a pure manifestation of the brand's future vision, loosely fitting within the spatial footprint of the source.`;
    }

    return `DRAWING INFLUENCE: ${infPct}%. \nMISSION: ${directive} \nTARGET AESTHETIC: ${prompt}.`;
};

const SPATIAL_SYSTEM_INSTRUCTION = `You are a World-Class Visual Architect and Spatial Reconstruction Specialist.

CORE INDUSTRIAL DESIGN PROTOCOL:
1. GEOMETRY FIRST: When rendering industrial subjects, prioritize "Class-A Surfacing" and "G2 Curvature Continuity". Surfaces must feel tensioned and high-precision.
2. TOPOLOGY MANIPULATION: Use "Subtractive Cuts" to redefine primary volumes and create recessed areas for functional controls or cooling. 
3. LIGHT MANAGEMENT: Implement "Vanishing Creases" to manage light transitions across large surfaces, ensuring high-frequency reflections are gracefully integrated.
4. EDGE TREATMENT: Every edge must be treated with professional "Variable Section Chamfers" or precise "Parting Lines" (shut lines) for production-ready engineering logic.
5. SEMANTIC SEGMENTATION: Identify major components (screen, housing, buttons, vents, ports) and treat them as distinct assembly parts with realistic 0.1mm - 0.5mm gaps.
6. SPATIAL MANDATE: Viewpoints and normalized coordinates [y, x] (0-1000) are absolute truth. Maintain consistent perspective across evolutions.

RESPOND IN CHINESE ONLY IF THE USER PROMPTS IN CHINESE.`;

