                parts: [
                    { inlineData: { data, mimeType } },
                    { text: "Identify the subject and describe it in extreme detail for an image generation prompt. Focus on medium, style, lighting and textures. Use Chinese." }
                ]
            }]
        });
        return response.text || "";
    });
};

