  const [recordingStatus, setRecordingStatus] = useState<'idle' | 'recording' | 'paused'>('idle');
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  const canvasRef = useRef<CanvasRef>(null);
  const chatRef = useRef<GeminiChatPanelRef>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const saveTimeoutRef = useRef<number | null>(null);

  const pasteCountRef = useRef(0);
  const lastPasteTimeRef = useRef(0);

  const selectedItem = selection.length === 1 ? items.find(it => it.id === selection[0]) || null : null;

  const centerOnItem = useCallback((item: CanvasItem, targetScale?: number) => {
    const scale = targetScale || Math.min(view.scale, 1.0);
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth;
    const centerX = leftPanelWidth + availableWidth / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (item.x + item.width / 2) * scale, y: centerY - (item.y + item.height / 2) * scale });
  }, [view.scale, showLayers, showHistory, isPropertiesPanelOpen]);

  const zoomToFit = useCallback(() => {
    if (items.length === 0) {
        setView({ x: 0, y: 0, scale: 1 });
        return;
    }
    const minX = Math.min(...items.map(i => i.x));
    const minY = Math.min(...items.map(i => i.y));
    const maxX = Math.max(...items.map(i => i.x + i.width));
    const maxY = Math.max(...items.map(i => i.y + i.height));
    const contentWidth = maxX - minX;
    const contentHeight = maxY - minY;
    const padding = 100;
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth - padding * 2;
    const availableHeight = window.innerHeight - padding * 2;
    const scale = Math.min(availableWidth / contentWidth, availableHeight / contentHeight, 1.5);
    const centerX = leftPanelWidth + (window.innerWidth - leftPanelWidth - rightPanelWidth) / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (minX + contentWidth / 2) * scale, y: centerY - (minY + contentHeight / 2) * scale });
  }, [items, showLayers, showHistory, isPropertiesPanelOpen]);

  /**
   * Recraft 风格排列算法：
   * 1. 优先保持 Y 轴一致（水平对齐）。
   * 2. 只有在右侧无限探测都被占用的情况下才尝试下方。
   */
  const findPlacementSpot = useCallback((width: number, height: number, itemsList: CanvasItem[], relativeTo?: CanvasItem, offsetIdx: number = 0) => {
    const spacing = 80; 

    if (itemsList.length === 0) {
        return { 
          x: (window.innerWidth / 2 - view.x) / view.scale - width / 2, 
          y: (window.innerHeight / 2 - view.y) / view.scale - height / 2 
        };
    }

    const ref = relativeTo || itemsList[itemsList.length - 1];
    let startX = ref.x + ref.width + spacing;
    let startY = ref.y; // 核心：默认 Y 轴对齐，不再斜向偏移

    const isOccupied = (tx: number, ty: number) => {
        return itemsList.some(it => {
            const overlapX = tx < it.x + it.width + 10 && tx + width + 10 > it.x;
            const overlapY = ty < it.y + it.height + 10 && ty + height + 10 > it.y;
            return overlapX && overlapY;
        });
    };

    let curX = startX + (offsetIdx * (width / 4));
    let curY = startY;
    let attempts = 0;

    // 向右持续探测空白
    while (isOccupied(curX, curY) && attempts < 50) {
        curX += spacing;
        attempts++;
    }

    // 如果向右探测太远（>5000px），则尝试换行
    if (attempts >= 50) {
        curX = ref.x;
        curY = ref.y + ref.height + spacing;
        attempts = 0;
        while (isOccupied(curX, curY) && attempts < 50) {
            curY += spacing;
            attempts++;
        }
    }

    return { x: curX, y: curY };
  }, [view.x, view.y, view.scale]);

  const handleFile = useCallback(async (file: File, x?: number, y?: number) => {
    const reader = new FileReader();
    reader.onload = async (event) => {
        const content = event.target?.result as string;
        const isVideo = file.type.startsWith('video/') || file.name.endsWith('.webm');
        const { width, height } = isVideo ? await getVideoDimensions(content) : await getImageDimensions(content);
        const displayWidth = 500;
        const displayHeight = (height * displayWidth) / width;

        setItems(prev => {
            let targetPos;
            if (x !== undefined && y !== undefined) {
                targetPos = { 
                  x: (x - view.x) / view.scale - displayWidth / 2, 
                  y: (y - view.y) / view.scale - displayHeight / 2 
                };
            } else {
                targetPos = findPlacementSpot(displayWidth, displayHeight, prev);
            }

            const newItem: CanvasItem = { 
              id: crypto.randomUUID(), 
              type: isVideo ? ItemType.VIDEO : ItemType.IMAGE, 
              x: targetPos.x, 
              y: targetPos.y, 
              width: displayWidth, 
              height: displayHeight, 
              rotation: 0, 
              content: content, 
              status: 'generated', 
              prompt: file.name, 
              aspectRatio: getClosestAspectRatio(width, height) 
            };
            setSelection([newItem.id]);
            return [...prev, newItem];
        });
    };
    reader.readAsDataURL(file);
  }, [view.x, view.y, view.scale, findPlacementSpot]);

  const handleCopy = useCallback((e: ClipboardEvent | null) => {
    if (e) {
      const target = e.target as HTMLElement;
      if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;
      const selectionText = window.getSelection()?.toString();
      if (selectionText && selectionText.length > 0) return;
    }
    if (selection.length === 0) return;
    const selectedItems = items.filter(it => selection.includes(it.id));
    const data = JSON.stringify(selectedItems);
    if (e) e.clipboardData?.setData('application/json/recreate-items', data);
    localStorage.setItem('recreate_clipboard', data);
    if (e) e.preventDefault();
  }, [selection, items]);

  const handlePaste = useCallback(async (e: ClipboardEvent) => {
    const target = e.target as HTMLElement;
    const tagName = target.tagName?.toUpperCase();
    if (tagName === 'INPUT' || tagName === 'TEXTAREA' || target.isContentEditable) return;

    let dataStr = e.clipboardData?.getData('application/json/recreate-items');
    if (!dataStr) {
      dataStr = localStorage.getItem('recreate_clipboard') || '';
    }

    if (dataStr) {
      try {
        const itemsToPaste = JSON.parse(dataStr) as CanvasItem[];
        if (itemsToPaste.length > 0) {
          e.preventDefault();
          const now = Date.now();
          if (now - lastPasteTimeRef.current > 2000) {
            pasteCountRef.current = 1;
          } else {
            pasteCountRef.current += 1;
          }
          lastPasteTimeRef.current = now;
          const offset = pasteCountRef.current * 24;

          const newItems = itemsToPaste.map(it => ({
            ...it,
            id: crypto.randomUUID(),
            x: it.x + offset,
            y: it.y + offset,
            status: 'generated' as const
          }));

          setItems(prev => [...prev, ...newItems]);
          setSelection(newItems.map(it => it.id));
          return;
        }
      } catch (err) {
        console.error("Paste parse error:", err);
      }
    }

    const clipboardItems = e.clipboardData?.items;
    if (!clipboardItems) return;
    for (let i = 0; i < clipboardItems.length; i++) {
        if (clipboardItems[i].type.indexOf("image") !== -1 || clipboardItems[i].type.indexOf("video") !== -1) {
            const file = clipboardItems[i].getAsFile();
            if (file) {
              e.preventDefault();
              handleFile(file);
            }
        }
    }
  }, [handleFile]);

  useEffect(() => {
    const handleDrop = (e: DragEvent) => {
        e.preventDefault();
        const files = Array.from(e.dataTransfer?.files || []);
        files.forEach(file => {
            if (file.type.startsWith('image/') || file.type.startsWith('video/') || file.name.endsWith('.webm')) {
                handleFile(file, e.clientX, e.clientY);
            }
        });
    };
    const handleDragOver = (e: DragEvent) => e.preventDefault();

    window.addEventListener('copy', handleCopy as any);
    window.addEventListener('paste', handlePaste);
    window.addEventListener('drop', handleDrop);
    window.addEventListener('dragover', handleDragOver);
    return () => {
        window.removeEventListener('copy', handleCopy as any);
        window.removeEventListener('paste', handlePaste);
        window.removeEventListener('drop', handleDrop);
        window.removeEventListener('dragover', handleDragOver);
    };
  }, [handleCopy, handlePaste, handleFile]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;

      if (e.key === 'Delete' || e.key === 'Backspace') {
        if (selection.length > 0) handleDeleteItems(selection);
      }
      if (e.key === ' ') {
        e.preventDefault();
        if (quickLookItem) setQuickLookItem(null);
        else if (selectedItem) setQuickLookItem(selectedItem);
      }
      if (e.key === 'Escape') { 
          setQuickLookItem(null); 
          if (editMode) setEditMode(false); 
          if (isPickingPoint) setIsPickingPoint(false);
          setExpressionState({ itemId: '', isOpen: false });
          setInferenceState({ itemId: '', isOpen: false });
          setTool('select');
      }
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.preventDefault();
        if (quickLookItem) {
            const assetItems = items.filter(it => (it.type === ItemType.IMAGE || it.type === ItemType.VIDEO) && it.content);
            if (assetItems.length > 0) {
                const currentIndex = assetItems.findIndex(it => it.id === quickLookItem.id);
                let nextIndex = currentIndex;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') nextIndex = (currentIndex + 1) % assetItems.length;
                else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') nextIndex = (currentIndex - 1 + assetItems.length) % assetItems.length;
                const nextItem = assetItems[nextIndex];
                setQuickLookItem(nextItem);
                setSelection([nextItem.id]);
                centerOnItem(nextItem);
            }
        } else if (selection.length > 0) {
            const step = e.shiftKey ? 10 : 1;
            const updates = selection.map(id => {
              const item = items.find(i => i.id === id);
              if (!item) return null;
              let nx = item.x, ny = item.y;
              if (e.key === 'ArrowUp') ny -= step;
              if (e.key === 'ArrowDown') ny += step;
              if (e.key === 'ArrowLeft') nx -= step;
              if (e.key === 'ArrowRight') nx += step;
              return { id, updates: { x: nx, y: ny } };
            }).filter(Boolean) as { id: string, updates: Partial<CanvasItem> }[];
            if (updates.length > 0) handleUpdateItems(updates);
        }
      }
      if (e.key.toLowerCase() === 'v') setTool('select');
      if (e.key.toLowerCase() === 'h') setTool('hand');
      if (e.key.toLowerCase() === 'r') setTool('point');
      if (e.key.toLowerCase() === 'c') setTool('capture');
      if (e.key.toLowerCase() === 'g') setShowGrid(prev => !prev);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selection, items, selectedItem, quickLookItem, editMode, view.scale, showLayers, showHistory, centerOnItem, isPickingPoint]);

  const startRecording = async (resolution: string) => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: { cursor: "always" } as any, audio: false });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.ondataavailable = (event) => { if (event.data.size > 0) recordedChunksRef.current.push(event.data); };
      mediaRecorder.onstop = () => {
        const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `Recraft-${new Date().getTime()}.webm`;
        a.click();
        setRecordingStatus('idle'); setRecordingTime(0);
        if (timerRef.current) window.clearInterval(timerRef.current);
      };
      mediaRecorder.start();
      setRecordingStatus('recording');
      timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch (err) { console.error(err); }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(track => track.stop());
  };

  useEffect(() => {
    const initLoad = async () => {
      const snapshots = await getAllSnapshots();
      if (snapshots.length > 0) setItems(snapshots[0].items);
      const recipes = await getAllRecipes();
      setAvailableRecipes(recipes);
    };
    initLoad();
  }, []);

  useEffect(() => {
    if (items.length === 0) return;
    if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
    saveTimeoutRef.current = window.setTimeout(async () => {
      const lastAsset = [...items].reverse().find(i => (i.type === ItemType.IMAGE || i.type === ItemType.VIDEO) && i.content);
      const snapshot: ProjectSnapshot = { id: crypto.randomUUID(), name: lastAsset?.prompt?.slice(0, 30) || 'Snapshot', items, thumbnail: (lastAsset?.type === ItemType.IMAGE ? lastAsset.content : ''), updatedAt: Date.now() };
      await saveSnapshot(snapshot);
    }, 2000);
  }, [items]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    files.forEach(file => handleFile(file));
  };

  const handleAddToCanvas = async (base64: string, promptText?: string, refId?: string) => {
    const { width, height } = await getImageDimensions(base64);
    let displayWidth = 512;
    let referenceId: string | null = refId || null;

    if (!referenceId) {
        if (selection.length === 1) {
            referenceId = selection[0];
        } else if (items.length > 0) {
            const assetItems = items.filter(it => it.type === ItemType.IMAGE || it.type === ItemType.VIDEO);
            if (assetItems.length > 0) referenceId = assetItems[assetItems.length - 1].id;
        }
    }

    setItems(currentItems => {
        const actualReferenceItem = referenceId ? currentItems.find(i => i.id === referenceId) : undefined;
        let targetDisplayHeight = (height * displayWidth) / width;

        if (actualReferenceItem) {
            const refRatio = actualReferenceItem.width / actualReferenceItem.height;
            const newRatio = width / height;
            displayWidth = actualReferenceItem.width;
            if (Math.abs(refRatio - newRatio) < 0.2) {
                targetDisplayHeight = actualReferenceItem.height;
                displayWidth = (width * targetDisplayHeight) / height;
            } else {
                targetDisplayHeight = (height * displayWidth) / width;
            }
        }

        const spot = findPlacementSpot(displayWidth, targetDisplayHeight, currentItems, actualReferenceItem);

        const newItem: CanvasItem = { 
          id: crypto.randomUUID(), 
          type: ItemType.IMAGE, 
          x: spot.x, 
          y: spot.y, 
          width: displayWidth, 
          height: targetDisplayHeight, 
          rotation: 0, 
          content: base64, 
          status: 'generated', 
          prompt: promptText || 'AI Created', 
          aspectRatio: getClosestAspectRatio(width, height) 
        };
        setSelection([newItem.id]);
        setTimeout(() => centerOnItem(newItem, 0.8), 50);
        return [...currentItems, newItem];
    });
  };

  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item)), []);
  const handleUpdateItems = useCallback((updates: { id: string, updates: Partial<CanvasItem> }[]) => setItems(prev => { const newItems = [...prev]; updates.forEach(({ id, updates: itemUpdates }) => { const idx = newItems.findIndex(i => i.id === id); if (idx !== -1) newItems[idx] = { ...newItems[idx], ...itemUpdates }; }); return newItems; }), []);
  const handleDeleteItems = useCallback((ids: string[]) => { setItems(prev => prev.filter(item => !ids.includes(item.id))); setSelection([]); }, []);

  const handleVisualPeelAction = async (itemId: string) => {
    const item = items.find(i => i.id === itemId);
    if (!item || !item.content) return;

    const nid = crypto.randomUUID();
    const spot = findPlacementSpot(item.width, item.height, items, item);

    setItems(prev => [...prev, {
        id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, 
        width: item.width, height: item.height, rotation: item.rotation, 
        content: '', status: 'loading', prompt: 'Visual De-shell Prototype', 
        aspectRatio: item.aspectRatio || '1:1', links: [item.id]
    }]);
    setSelection([nid]);

    try {
        const essence = await extractSubjectEssence(item.content);
        const peeledUrl = await generateVisualPeel(item.content, essence, item.aspectRatio || '1:1');
        const { width, height } = await getImageDimensions(peeledUrl);
        setItems(prev => prev.map(i => i.id === nid ? { 
            ...i, 
            content: peeledUrl, 
            status: 'generated',
            essence: essence,
            height: (height * i.width) / width
        } : i));
    } catch (e) {
        setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i));
    }
  };

  const handleGenerate = async (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>, existingItem?: CanvasItem, manualRefs?: string[]) => {
    const rawPrompt = overridePrompt || (items.find(i => i.id === id)?.prompt || "Professional design");

    // 如果是演化指令，更新全局记忆
    const isEvolution = rawPrompt.startsWith('__EVOLUTION__');
    if (isEvolution) {
        const level = parseInt(rawPrompt.split('|')[1]);
        if (!isNaN(level)) setCurrentEvolutionLevel(level);
    }

    let promptsToProcess: string[] = [];
    let inferenceCfgs: InferenceSettings[] = [];

    const isInference = rawPrompt.startsWith('inference:');

    if (isInference) {
        const [_, data] = rawPrompt.split(':');
        const [p, inf, countStr, recipeId, subType] = data.split('|');

        if (p === '__VISUAL_PEEL__') {
            handleVisualPeelAction(id);
            return;
        }

        const influence = parseFloat(inf);
        const count = parseInt(countStr) || 1;
        const subjectType = subType || 'industrial';

        if (count > 1) {
            inferenceCfgs = [
                { prompt: p, influence: 0.95, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any },
                { prompt: p, influence: 0.75, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any },
                { prompt: p, influence: 0.55, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any },
            ];
            promptsToProcess = inferenceCfgs.map(s => s.prompt);
        } else {
            inferenceCfgs = [{ prompt: p, influence, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any }];
            promptsToProcess = [p];
        }
    } else {
        const separationKeywords = ["分别", "各自", "each", "separately"];
        const hasSeparationIntent = separationKeywords.some(kw => rawPrompt.includes(kw));

        if (hasSeparationIntent) {
            let cleanPrompt = rawPrompt.replace(/^(?:我想|请|能不能|帮我|能否)?(?:分别生成|分别设计|分别|生成|设计|各自生成|各自设计|each|separately generate|generate separately)\s*/i, '');
            const subjects = cleanPrompt.split(/(?:\s*[，、,]\s*|\s+和\s+|\s+以及\s+|\s+与\s+|\s+与及\s+|\s+plus\s+|\s+and\s+|\s+&\s+)/i)
                .map(s => s.trim())
                .filter(s => s.length >= 1);
            if (subjects.length > 1) promptsToProcess = subjects;
            else promptsToProcess = [rawPrompt];
        } else {
            promptsToProcess = [rawPrompt];
        }
    }

    const sourceItem = items.find(i => i.id === id);
    const contextItem = sourceItem || (selection.length === 1 ? items.find(it => it.id === selection[0]) : null);

    let targetW = 512;
    let targetH = 512;
    let ratioToUse = settings?.ratio || '1:1';

    if (existingItem) {
      targetW = existingItem.width;
      targetH = existingItem.height;
    } else if (manualRefs && manualRefs.length > 0) {
      const dims = await getImageDimensions(manualRefs[0]);
      targetW = dims.width;
      targetH = dims.height;
      ratioToUse = getClosestAspectRatio(dims.width, dims.height);
    } else if (contextItem) {
      targetW = contextItem.width;
      targetH = contextItem.height;
      ratioToUse = contextItem.aspectRatio || getClosestAspectRatio(targetW, targetH);
    } else {
      const ratioObj = ASPECT_RATIOS.find(r => r.id === ratioToUse) || ASPECT_RATIOS[0];
      targetW = ratioObj.width;
      targetH = ratioObj.height;
    }

    const styleId = settings?.style || 'industrial';
    const styleObj = STYLES.find(s => s.id === styleId) || STYLES[1];

    let currentTempItems = [...items];
    const tasks: { nid: string, prompt: string, infCfg?: InferenceSettings }[] = [];

    promptsToProcess.forEach((promptText, idx) => {
        const nid = crypto.randomUUID();
        const spot = findPlacementSpot(targetW, targetH, currentTempItems, contextItem, idx);

        let finalPrompt = promptText;
        if (isEvolution && contextItem) {
            const evolutionLevel = parseInt(rawPrompt.split('|')[1]);
            finalPrompt = getEvolutionLogic(evolutionLevel, contextItem.prompt || "industrial design");
        }

        const infCfg = inferenceCfgs[idx] || undefined;

        const newItem: CanvasItem = { 
            id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, 
            width: targetW, height: targetH, rotation: (existingItem || contextItem)?.rotation || 0, 
            content: '', status: 'loading', prompt: finalPrompt, aspectRatio: ratioToUse, 
            links: contextItem ? [contextItem.id] : [],
            spatialConfig: settings?.spatialConfig,
            inferenceInfluence: infCfg?.influence
        };
        currentTempItems.push(newItem);
        tasks.push({ nid, prompt: finalPrompt, infCfg });
    });

    setItems(currentTempItems);
    setSelection(tasks.map(t => t.nid));

    tasks.forEach(async ({ nid, prompt: promptToUse, infCfg }) => {
        try {
            let recipeTxt = "";
            const currentRecipeId = infCfg?.recipeId || settings?.recipeId;
            if (currentRecipeId) {
                const recipe = availableRecipes.find(r => r.id === currentRecipeId);
                if (recipe) recipeTxt = recipe.instruction;
            }

            let url: string;
            if (infCfg && contextItem && contextItem.content) {
                url = await generateWithReferences(promptToUse, [{ label: 'Source Volume', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig || contextItem.spatialConfig, recipeTxt, infCfg);
            } else if (isEvolution && contextItem && contextItem.content) {
                url = await generateWithReferences(promptToUse, [{ label: 'Evolution Source', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig || contextItem.spatialConfig, recipeTxt);
            } else if (manualRefs && manualRefs.length > 0) {
              const refs = manualRefs.map((r, idx) => ({ label: `Ref ${idx}`, base64: r }));
              url = await generateWithReferences(promptToUse, refs, ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig, recipeTxt);
            } else if (contextItem && contextItem.content) {
              url = await generateWithReferences(promptToUse, [{ label: 'Source', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig || contextItem.spatialConfig, recipeTxt);
            } else {
              url = await generateImage(promptToUse, styleObj.promptSuffix, ratioToUse, 1.0, settings?.resolution || '1K', settings?.spatialConfig, recipeTxt);
            }

            const { width, height } = await getImageDimensions(url);
            setItems(prev => prev.map(i => i.id === nid ? { 
              ...i, 
              content: url, 
              status: 'generated',
              height: (height * i.width) / width,
              aspectRatio: getClosestAspectRatio(width, height)
            } : i));
        } catch (e: any) { 
          setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); 
        }
    });
  };

  /**
   * 工业设计智能演化核心逻辑
   * 采用硬性 CAD 指令集，根据演化强度（0-100）阶梯式推进设计深度。
   */
  const getEvolutionLogic = (level: number, basePrompt: string) => {
      let logic = "";
      const perspectiveConstraint = "CORE PROTOCOL: Maintain the ABSOLUTE camera perspective and spatial orientation of the reference image. The evolved object MUST occupy the exact same 3D bounding box.";
      const classA = "Focus on Class-A surfaces: ensure smooth, tensioned surfaces with G2 Curvature Continuity at all transitions.";
      const secondaryFeatures = "Detailing: Refine all primary feature lines and add clear secondary features such as precise parting lines (shut lines), functional buttons, or vents.";
      const subtractiveCut = "Advanced Volumetric Manipulation: Confidently redefine major surface volumes using Subtractive Cut logic. Use Vanishing Creases to gracefully manage surface transitions and capture dramatic studio light.";
      const edgeTreatment = "Edge Integrity: Apply Variable Section Chamfers to all structural edges to ensure sophisticated light-to-shadow transitions and a production-ready finish.";
      const productionLogic = "Final Requirement: The result must be a production-ready, logical, and exquisite industrial design prototype with professional CMF implementation.";

      if (level <= 25) {
          // Tier 1: Surface Polish
          logic = `${classA} Remove AI visual noise and refine the current forms into high-precision CAD geometry. ${perspectiveConstraint}`;
      } else if (level <= 60) {
          // Tier 2: Feature Detailing
          logic = `${classA} ${secondaryFeatures} ${edgeTreatment} Focus on sharpening the character lines of the product. ${perspectiveConstraint}`;
      } else if (level <= 85) {
          // Tier 3: Structural Reconstruction
          logic = `${subtractiveCut} ${secondaryFeatures} ${edgeTreatment} Boldly rethink the functional layout while respecting the original volume. ${perspectiveConstraint}`;
      } else {
          // Tier 4: Radical Evolution
          logic = `Complete industrial paradigm evolution. ${subtractiveCut} ${edgeTreatment} ${productionLogic} Re-imagine the design entirely using advanced future-tech aesthetic logic while keeping the exact source viewpoint. ${perspectiveConstraint}`;
      }

      return `ID EVOLUTION MANDATE (Level ${level}): ${logic} \nPrimary Concept Context: ${basePrompt}. \nDO NOT rotate the object. DO NOT change the art style.`;
  };

  const handleApplyEdit = async (prompt: string) => {
    if (!selectedItem || !canvasRef.current) return;
    const maskData = await canvasRef.current.getMaskData();
    if (!maskData) return;
    const nid = crypto.randomUUID();
    const spot = findPlacementSpot(selectedItem.width, selectedItem.height, items, selectedItem);
    const newItem: CanvasItem = {
        id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: selectedItem.width, height: selectedItem.height, rotation: selectedItem.rotation,
        content: '', status: 'loading', prompt: prompt, aspectRatio: selectedItem.aspectRatio || '1:1', links: [selectedItem.id]
    };
    setItems(prev => [...prev, newItem]);
    setSelection([nid]);
    setEditMode(false); setSegments([]);
    try {
        const url = await editImage(selectedItem.content, prompt, selectedItem.aspectRatio || '1:1', true);
        const { width, height } = await getImageDimensions(url);
        setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated', height: (height * i.width) / width } : i));
        const createdItem = items.find(i => i.id === nid);
        if (createdItem) centerOnItem(createdItem);
    } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
  };

  const handleJSONAnalysis = async (id: string) => {
    const item = items.find(i => i.id === id);
    if (!item || !item.content) return;
    setIsAnalyzingJSON(true);
    try { const result = await detectImageJSONSegments(item.content); setSegments(result.segments || []); }
    catch (e) { console.error(e); } finally { setIsAnalyzingJSON(false); }
  };

  const getNextGlobalPointLabel = (currentItems: CanvasItem[]) => {
    let maxLabelNum = 0;
    currentItems.forEach(it => {
        it.identifiedPoints?.forEach(p => {
            const num = parseInt(p.label, 10);
            if (!isNaN(num) && num > maxLabelNum) maxLabelNum = num;
        });
    });
    return (maxLabelNum + 1).toString();
  };

  const handlePickPoint = async (itemId: string, y: number, x: number) => {
      const item = items.find(i => i.id === itemId);
      if (!item || !item.content) return;
      if (tool === 'point') {
          setItems(prev => {
              const nextLabel = getNextGlobalPointLabel(prev);
              const newPoint: IdentifiedPoint = { id: crypto.randomUUID(), y, x, label: nextLabel };
              chatRef.current?.addPointReference(itemId, item.content, nextLabel, [y, x]);
              return prev.map(it => it.id === itemId ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), newPoint] } : it);
          });
          return;
      }
      try {
          const aiLabel = await identifyPoint(item.content, y, x);
          setItems(prev => {
              const nextLabel = getNextGlobalPointLabel(prev);
              const newPoint: IdentifiedPoint = { id: crypto.randomUUID(), y, x, label: nextLabel, description: aiLabel };
              chatRef.current?.addPointReference(itemId, item.content, nextLabel, [y, x]);
              return prev.map(it => it.id === itemId ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), newPoint] } : it);
          });
      } catch (e) { console.error(e); }
  };

  const handleRemoveObjectAtPoint = (itemId: string, pointId: string) => {
    const item = items.find(i => i.id === itemId);
    const point = item?.identifiedPoints?.find(p => p.id === pointId);
    if (item && point && chatRef.current) chatRef.current.requestObjectRemoval(item.id, item.content || '', point.label, [point.y, point.x]);
    handleDeletePointLocal(itemId, pointId);
  };

  const handleDeletePointLocal = (itemId: string, pointId: string) => {
    setItems(prev => prev.map(it => it.id === itemId ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pointId) } : it));
  };

  const handleMovePoint = (itemId: string, pointId: string, ny: number, nx: number) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, identifiedPoints: item.identifiedPoints?.map(p => p.id === pointId ? { ...p, y: ny, x: nx } : p) } : item));
  };

  const handleMovePointEnd = (itemId: string, pointId: string, from: [number, number], to: [number, number]) => {
    const item = items.find(i => i.id === itemId);
    const point = item?.identifiedPoints?.find(p => p.id === pointId);
    if (point && chatRef.current && item?.content) chatRef.current.appendMovementDescription(item.id, item.content, point.label, from, to);
  };

  const handleStartPickPoint = async (id: string, temperature: number) => {
      const item = items.find(i => i.id === id);
      if (!item || !item.content) return;
      setIsPickingPoint(true); setPickingTargetId(id);
      try {
          const rawPoints = await detectAllPoints(item.content, temperature);
          setItems(prev => {
              let currentGlobalMax = 0;
              prev.forEach(it => {
                  it.identifiedPoints?.forEach(p => {
                      const num = parseInt(p.label, 10);
                      if (!isNaN(num) && num > currentGlobalMax) currentGlobalMax = num;
                  });
              });
              const newIdentifiedPoints: IdentifiedPoint[] = rawPoints.map((p, idx) => {
                  return { id: crypto.randomUUID(), y: p.point[0], x: p.point[1], label: (currentGlobalMax + idx + 1).toString(), description: p.label };
              });
              return prev.map(it => it.id === id ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), ...newIdentifiedPoints] } : it);
          });
      } catch (e) { console.error(e); } finally { setIsPickingPoint(false); setPickingTargetId(null); }
  };

  const handleSyncPointsToGemini = (id: string) => {
      const item = items.find(it => it.id === id);
      if (item && item.identifiedPoints && item.content && chatRef.current) {
          const pointsPayload = item.identifiedPoints.map(p => ({ label: p.label, point: [p.y, p.x] as [number, number] }));
          chatRef.current.addBulkPointReferences(item.id, item.content, pointsPayload);
      }
  };

  const handlePointTagClick = (item: CanvasItem, pt: IdentifiedPoint) => chatRef.current?.addPointReference(item.id, item.content, pt.label, [pt.y, pt.x]);
  const handleToggleFit = () => { if (selection.length === 1) { const item = items.find(i => i.id === selection[0]); if (item) centerOnItem(item); } else { zoomToFit(); } };

  const handleCaptureRegion = async (region: Rect, action: 'chat' | 'canvas', annotations: any[] = []) => {
      const scale = 2; 
      const canvas = document.createElement('canvas');
      canvas.width = region.width * scale;
      canvas.height = region.height * scale;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.scale(scale, scale);
      ctx.translate(-region.x, -region.y);

      for (const item of items) {
          const intersects = !(item.x > region.x + region.width || 
                             item.x + item.width < region.x || 
                             item.y > region.y + region.height || 
                             item.y + item.height < region.y);

          if (intersects && item.content) {
            if (item.type === ItemType.IMAGE) {
              const img = new Image();
              img.src = item.content;
              await new Promise(resolve => {
                  img.onload = () => {
                      ctx.save();
                      ctx.translate(item.x + item.width/2, item.y + item.height/2);
                      ctx.rotate((item.rotation || 0) * Math.PI / 180);
                      ctx.drawImage(img, -item.width/2, -item.height/2, item.width, item.height);
                      ctx.restore();
                      resolve(null);
                  };
                  img.onerror = () => resolve(null);
              });
            } else if (item.type === ItemType.VIDEO) {
                const videoEl = document.querySelector(`[data-item-id="${item.id}"] video`) as HTMLVideoElement;
                if (videoEl) {
                    ctx.save();
                    ctx.translate(item.x + item.width/2, item.y + item.height/2);
                    ctx.rotate((item.rotation || 0) * Math.PI / 180);
                    ctx.drawImage(videoEl, -item.width/2, -item.height/2, item.width, item.height);
                    ctx.restore();
                }
            }
          }
      }

      annotations.forEach(anno => {
          ctx.strokeStyle = anno.color;
          ctx.fillStyle = anno.color;
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';

          if (anno.type === 'arrow') {
              const [p1, p2] = anno.points;
              ctx.lineWidth = anno.size;
              ctx.beginPath();
              ctx.moveTo(p1.x, p1.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.stroke();

              const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
              ctx.save();
              ctx.translate(p2.x, p2.y);
              ctx.rotate(angle);
              ctx.beginPath();
              ctx.moveTo(0, 0);
              ctx.lineTo(-15, -7);
              ctx.lineTo(-15, 7);
              ctx.closePath();
              ctx.fill();
              ctx.restore();
          } else if (anno.type === 'number') {
              const [p] = anno.points;
              ctx.beginPath();
              ctx.arc(p.x, p.y, 12, 0, Math.PI * 2);
              ctx.fill();
              ctx.fillStyle = 'white';
              ctx.font = 'black 14px Inter';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              ctx.fillText(anno.text, p.x, p.y);
          } else if (anno.type === 'text') {
              const [p] = anno.points;
              ctx.font = 'bold 16px Inter';
              ctx.fillText(anno.text, p.x, p.y);
          } else if (anno.type === 'rectangle') {
              const [p1, p2] = anno.points;
              ctx.lineWidth = anno.size;
              ctx.strokeRect(Math.min(p1.x, p2.x), Math.min(p1.y, p2.y), Math.abs(p1.x - p2.x), Math.abs(p1.y - p2.y));
          } else if (anno.type === 'circle') {
              const [p1, p2] = anno.points;
              const r = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
              ctx.lineWidth = anno.size;
              ctx.beginPath();
              ctx.arc(p1.y, p1.x, r, 0, Math.PI * 2);
              ctx.stroke();
          } else if (anno.type === 'brush') {
              ctx.lineWidth = anno.size;
              ctx.beginPath();
              anno.points.forEach((p, i) => {
                  if (i === 0) ctx.moveTo(p.x, p.y);
                  else ctx.lineTo(p.x, p.y);
              });
              ctx.stroke();
          }
      });

      const base64 = canvas.toDataURL('image/png');
      if (action === 'chat') {
          chatRef.current?.addExternalAttachment(crypto.randomUUID(), base64);
          setTool('select');
      } else {
          handleAddToCanvas(base64, "Region Capture");
          setTool('select');
      }
  };

  const handleFloatingAction = async (id: string, action: string) => {
    const selectedItems = items.filter(i => selection.includes(i.id));
    const firstItem = selectedItems[0];
    if (!firstItem) return;

    if (action.startsWith('expr:')) {
      const expr = action.split(':')[1];
      handleGenerate(firstItem.id, `Change to ${expr}`);
      return;
    }

    if (action.startsWith('inference:')) {
        const data = action.split(':')[1];
        handleGenerate(firstItem.id, `inference:${data}`);
        return;
    }

    // 处理演化强度记忆化触发
    if (action.startsWith('evolve_with_level:')) {
        const level = parseInt(action.split(':')[1]);
        setCurrentEvolutionLevel(level);
        handleGenerate(firstItem.id, `__EVOLUTION__|${level}`);
        return;
    }

    switch(action) {
      case 'visual_peel':
        handleVisualPeelAction(firstItem.id);
        break;
      case 'evolve':
        // 使用记忆的强度进行演化，无需二次确认
        handleGenerate(firstItem.id, `__EVOLUTION__|${currentEvolutionLevel}`);
        break;
      case 'expression':
        setExpressionState({ itemId: firstItem.id, isOpen: true });
        break;
      case 'inference':
        setInferenceState({ itemId: firstItem.id, isOpen: true });
        break;
      case 'variation':
        handleGenerate(firstItem.id, 'Generate variation');
        break;
      case 'remove_bg':
        handleGenerate(firstItem.id, 'Remove background');
        break;
      case 'upscale':
        handleGenerate(firstItem.id, 'Upscale');
        break;
      case 'edit':
        setEditMode(true);
        setIsPropertiesPanelOpen(true);
        break;
      case 'delete':
        handleDeleteItems(selection);
        break;
      case 'copy':
        handleCopy(null);
        break;
      case 'extract_recipe':
        setIsExtractingRecipe(true);
        try {
            const imgs = selectedItems.filter(it => it.content).map(it => it.content!);
            const instruction = await extractDesignRecipe(imgs, 0);
            setExtractedRecipe({ instruction, images: imgs });
        } catch (e) {
            console.error("Extraction failed", e);
        } finally {
            setIsExtractingRecipe(false);
        }
        break;
    }
  };

  const handleSaveRecipe = async (name: string, finalInstruction: string) => {
    if (!extractedRecipe) return;
    setIsSavingRecipe(true);
    try {
        const recipe: DesignRecipe = {
            id: crypto.randomUUID(),
            name,
            instruction: finalInstruction,
            exampleImages: extractedRecipe.images.slice(0, 3),
            createdAt: Date.now()
        };
        await saveRecipe(recipe);
        const recipes = await getAllRecipes();
        setAvailableRecipes(recipes);
        setExtractedRecipe(null);
    } catch (e) {
        console.error("Save failed", e);
    } finally {
        setIsSavingRecipe(false);
    }
  };

  const floatingColors = [
    { id: 'red', value: '#ef4444' },
    { id: 'yellow', value: '#facc15' },
    { id: 'green', value: '#22c55e' },
    { id: 'blue', value: '#3b82f6' },
    { id: 'white', value: '#ffffff' },
  ];

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative">
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => { const spot = findPlacementSpot(800, 600, items); const f: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: spot.x, y: spot.y, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' }; setItems(p => [...p, f]); setSelection([f.id]); }} recordingStatus={recordingStatus} onStartRecording={startRecording} onStopRecording={stopRecording} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={recordingTime} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection.length > 0 ? selection[0] : null} onSelectItem={(id) => { setSelection([id]); const item = items.find(i => i.id === id); if (item) centerOnItem(item); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => setItems(snap.items)} />
      <div className="w-full h-full">
        <Canvas 
            ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={it => setItems(p => [...p, it])} updateItem={handleUpdateItem} updateItems={handleUpdateItems} 
            onContextMenu={(e, id) => {
                if (tool === 'point' || tool === 'capture') { setTool('select'); return; }
