                            <polygon points="0 0, 10 3.5, 0 7" fill="currentColor" />
                        </marker>
                    </defs>
                    {annotations.map(anno => {
                        if (anno.type === 'arrow') {
                            const [p1, p2] = anno.points;
                            return (
                                <line 
                                    key={anno.id} 
                                    x1={p1.x} y1={p1.y} x2={p2.x} y2={p2.y} 
                                    stroke={anno.color} 
                                    strokeWidth={anno.size} 
                                    markerEnd="url(#arrowhead)" 
                                    className="text-current"
                                    style={{ color: anno.color }}
                                />
                            );
                        }
                        if (anno.type === 'number') {
                            const [p] = anno.points;
                            return (
                                <g key={anno.id}>
                                    <circle cx={p.x} cy={p.y} r={12} fill={anno.color} />
                                    <text x={p.x} y={p.y} fill="white" textAnchor="middle" dy=".3em" fontSize="14" fontWeight="black">{anno.text}</text>
                                </g>
                            );
                        }
                        if (anno.type === 'text') {
                            const [p] = anno.points;
                            return (
                                <text key={anno.id} x={p.x} y={p.y} fill={anno.color} fontSize="16" fontWeight="bold">{anno.text}</text>
                            );
                        }
                        if (anno.type === 'rectangle') {
                            const [p1, p2] = anno.points;
                            const rx = Math.min(p1.x, p2.x);
                            const ry = Math.min(p1.y, p2.y);
                            const rw = Math.abs(p1.x - p2.x);
                            const rh = Math.abs(p1.y - p2.y);
                            return (
                                <rect 
                                    key={anno.id} x={rx} y={ry} width={rw} height={rh} 
                                    stroke={anno.color} strokeWidth={anno.size} fill="none" 
                                />
                            );
                        }
                        if (anno.type === 'circle') {
                            const [p1, p2] = anno.points;
                            const radius = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
                            return (
                                <circle 
                                    key={anno.id} cx={p1.x} cy={p1.y} r={radius} 
                                    stroke={anno.color} strokeWidth={anno.size} fill="none" 
                                />
                            );
                        }
                        if (anno.type === 'brush') {
                            const pathData = anno.points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');
                            return (
                                <path 
                                    key={anno.id} d={pathData} 
                                    stroke={anno.color} strokeWidth={anno.size} fill="none" 
                                    strokeLinecap="round" strokeLinejoin="round"
                                />
                            );
                        }
                        return null;
                    })}
               </svg>

               {/* Annotation Text Input */}
               {annotationTextInput && (
                  <div 
                    className="absolute z-[160]"
                    style={{ 
                        left: (annotationTextInput.x - captureRect.x) * view.scale, 
                        top: (annotationTextInput.y - captureRect.y) * view.scale,
                        transform: 'translate(-50%, -100%)'
                    }}
                  >
                      <input 
                        ref={annotationTextInputRef}
                        type="text"
                        value={annotationTextInput.value}
                        onChange={e => setAnnotationTextInput({...annotationTextInput, value: e.target.value})}
                        onBlur={handleAnnotationTextConfirm}
                        onKeyDown={e => e.key === 'Enter' && handleAnnotationTextConfirm()}
                        className="bg-white border-2 border-indigo-500 rounded-lg px-3 py-1 text-sm font-bold text-zinc-900 outline-none shadow-xl min-w-[120px]"
                        placeholder="输入备注..."
                      />
                  </div>
               )}

               {/* Capture Toolbar */}
               {showCaptureMenu && (
                  <div 
                    className="absolute top-full mt-4 left-1/2 -translate-x-1/2 flex flex-col items-center gap-3 animate-in slide-in-from-top-4 duration-300 pointer-events-auto"
                    onMouseDown={e => e.stopPropagation()}
                  >
                     {/* Annotation Tool Selection Bar */}
                     <div className="flex items-center gap-1.5 bg-[#121214] border border-white/10 p-1.5 rounded-2xl shadow-3xl">
                        <div className="flex items-center gap-1 border-r border-white/5 pr-2 mr-2">
                            {[
                                { id: 'brush', icon: <PenIcon className="w-4 h-4" />, label: '涂鸦' },
                                { id: 'arrow', icon: <ArrowIcon className="w-4 h-4" />, label: '箭头' },
                                { id: 'rectangle', icon: <SquareIcon className="w-4 h-4" />, label: '矩形' },
                                { id: 'circle', icon: <CircleIcon className="w-4 h-4" />, label: '圆形' },
                                { id: 'text', icon: <TypeIcon className="w-4 h-4" />, label: '文本' },
                                { id: 'number', icon: <ListOrderedIcon className="w-4 h-4" />, label: '序号' },
                                { id: 'eraser', icon: <EraserIcon className="w-4 h-4" />, label: '全清' },
                            ].map(at => (
                                <button 
                                    key={at.id}
                                    onClick={() => {
                                        if (at.id === 'eraser') {
                                            setAnnotations([]);
                                        } else {
                                            setActiveAnnotationTool(activeAnnotationTool === at.id ? 'none' : at.id as any);
                                        }
                                    }}
                                    className={`p-2.5 rounded-xl transition-all ${activeAnnotationTool === at.id ? 'bg-indigo-600 text-white shadow-lg scale-105' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`}
                                    title={at.label}
                                >
                                    {at.icon}
                                </button>
                            ))}
                        </div>

                        {/* Color Selection */}
                        <div className="flex items-center gap-2 pr-2 border-r border-white/5 mr-2">
                            {annotationColors.map(c => (
                                <button 
                                    key={c.id}
                                    onClick={() => setAnnotationColor(c.value)}
                                    className={`w-6 h-6 rounded-full border-2 transition-all hover:scale-110 ${annotationColor === c.value ? 'border-white ring-2 ring-indigo-500/20' : 'border-transparent opacity-60 hover:opacity-100'}`}
                                    style={{ backgroundColor: c.value }}
                                />
                            ))}
                        </div>

                        <button 
                            onClick={() => setAnnotations(prev => prev.slice(0, -1))}
                            className="p-2.5 text-zinc-500 hover:text-white hover:bg-white/5 rounded-xl transition-all"
                            title="撤销 (Undo)"
                        >
                            <UndoIcon className="w-4 h-4" />
                        </button>
                     </div>

                     {/* Action Buttons Bar */}
                     <div className="flex items-center gap-2 bg-[#0c0c0e] border border-white/10 p-2 rounded-2xl shadow-3xl">
                        <button 
                          onClick={() => { 
                            onCaptureRegion?.(captureRect, 'chat', annotations); 
                            setCaptureRect(null); 
                            setShowCaptureMenu(false); 
                            setAnnotations([]);
                          }}
                          className="flex items-center gap-3 px-5 py-3 bg-[#5546fe] hover:bg-indigo-500 text-white rounded-xl transition-all group"
                        >
                            <MessageCircleIcon className="w-4.5 h-4.5 group-hover:scale-110 transition-transform" />
                            <span className="text-[12px] font-black uppercase tracking-[0.2em]">发送到对话</span>
                        </button>
                        <button 
                          onClick={() => { 
                            onCaptureRegion?.(captureRect, 'canvas', annotations); 
                            setCaptureRect(null); 
                            setShowCaptureMenu(false); 
                            setAnnotations([]);
                          }}
                          className="flex items-center gap-3 px-5 py-3 bg-zinc-800 hover:bg-zinc-700 text-white rounded-xl transition-all group"
                        >
                            <PlusIcon className="w-4.5 h-4.5 group-hover:rotate-90 transition-transform" />
                            <span className="text-[12px] font-black uppercase tracking-[0.2em]">作为新图</span>
                        </button>
                        <div className="w-px h-6 bg-white/10 mx-1" />
                        <button 
                          onClick={() => { 
                            setCaptureRect(null); 
                            setShowCaptureMenu(false); 
                            setAnnotations([]);
                          }}
                          className="p-3 text-zinc-500 hover:text-white transition-colors"
                        >
                            <XIcon className="w-5 h-5" />
                        </button>
                     </div>
                  </div>
               )}
            </div>
          )}
        </div>
      )}

      <svg className={`absolute inset-0 pointer-events-none origin-top-left z-30 ${!isInteracting ? 'transition-transform duration-[600ms] cubic-bezier(0.2, 0.0, 0, 1)' : ''}`} style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})` }}>
          {snapLines.map((line, i) => ( 
            <line key={i} x1={line.x !== undefined ? line.x : -10000} y1={line.y !== undefined ? line.y : -10000} x2={line.x !== undefined ? line.x : 10000} y2={line.y !== undefined ? line.y : 10000} stroke="#3b82f6" strokeWidth={2/view.scale} strokeDasharray="6 6" /> 
          ))}
      </svg>
    </div>
  );
});

