            })}

            {/* 当前手柄位置预览 */}
            <circle 
                cx={currentPos.x} cy={currentPos.y} r="8" 
                fill={mode === 'evolution' ? "#8b80ff" : "#5546fe"} 
                className={`shadow-2xl ${isDragging ? "" : "transition-all duration-300"}`}
                style={{ filter: 'drop-shadow(0 0 8px rgba(139, 128, 255, 0.5))' }}
            />
            <circle 
                cx={currentPos.x} cy={currentPos.y} r="3" 
                fill="white" 
