                                        if (!clipboardData) return;

                                        const internalData = clipboardData.getData('application/json/recreate-items');
                                        if (internalData) {
                                            try {
                                                const canvasItems = JSON.parse(internalData);
                                                if (Array.isArray(canvasItems)) {
                                                    const plainText = clipboardData.getData('text/plain');
                                                    if (!plainText) { e.preventDefault(); }
                                                    for (const canvasItem of canvasItems) {
                                                        const typedItem = canvasItem as { content?: string; id?: string };
                                                        if (typedItem.content && typedItem.content.startsWith('data:image')) {
                                                            await ensureAttachment(typedItem.id || null, typedItem.content);
