                                        }

                                        const clipboardItems = clipboardData.items;
                                        if (clipboardItems) {
                                            const itemsArray = Array.from(clipboardItems) as DataTransferItem[];
                                            for (const dataItem of itemsArray) {
                                                if (dataItem && dataItem.kind === 'file' && dataItem.type.indexOf('image') !== -1) {
                                                    const file = dataItem.getAsFile();
                                                    if (file instanceof File) {
                                                        const reader = new FileReader();
                                                        reader.onload = async (event: ProgressEvent<FileReader>) => {
                                                            const base64 = event.target?.result;
                                                            if (typeof base64 === 'string') {
                                                                await handleSendToContext(base64);
                                                            }
                                                        };
                                                        reader.readAsDataURL(file);
                                                    }
                                                }
                                            }
                                        }
                                    }}
