                                    {isLoading ? <RefreshIcon className="w-7 h-7 animate-spin" /> : <SendIcon className="w-7 h-7" />}
                                </button>
                            </div>
                        </div>
                    </div>
                  )}
              </div>
          </div>
        )}
        {isMinimized && (
