        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `Analyze this subject. Strip away all complex textures, colors, and environment. Describe it as a "Primitive White Essence" or "Master Model" prompt. 
Example for a car: "A minimalist white clay prototype of a sleek aerodynamic sports car, no windows or lights."
Example for a character: "A simple matte white sculpture of a stylized rabbit, focus on silhouette and basic form."
Output ONLY the short prompt string in English.` }
                ]
            }]
        });
        return response.text?.trim() || "Minimalist master model";
    });
};

