            const data = base64.split(',')[1] || base64;
            const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';
            parts.push({ inlineData: { data, mimeType } });

            if (baselineIndex !== undefined && i === baselineIndex) {
                parts.push({ text: `[REFERENCE BASELINE IMAGE]: This is the starting point.` });
            } else if (baselineIndex !== undefined) {
                parts.push({ text: `[REFINED TARGET SAMPLE]: This is a superior design outcome.` });
            }
        });

        let prompt = "";
        if (baselineIndex !== undefined) {
            prompt = `As a Senior Industrial Design Critic, analyze the transformation from the Baseline image to the Refined Target samples.
1. Identify the specific "Evolutionary Steps" and technical improvements that occurred (e.g., from generic radii to G2 continuity, from basic plastic to premium CMF textures).
2. Distill these changes into a "Transformation Logic" or "Refinement Recipe".
3. The goal is to describe HOW to upgrade the baseline aesthetic to match the refined targets.
4. Output a bulleted list of 4 key refinement instructions in English, followed by a 1-sentence evolution summary in Chinese.`;
        } else {
            prompt = `As a Senior Industrial Design Critic, analyze these provided design examples for shared DNA.
1. Identify the recurring design patterns, CMF (Color, Material, Finish), and structural refinement details that make these examples superior.
2. Focus on "High-Level" technical commonalities (e.g., specific parting line logic, monolithic unibody language).
3. Ignore the specific product category; extract only the "Global Aesthetic Recipe".
4. Output a bulleted list of 4 key technical instructions in English, followed by a 1-sentence aesthetic summary in Chinese.`;
        }

        parts.push({ text: prompt });

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{ parts }],
            config: {
                systemInstruction: "You are an expert visual architect capable of Delta Analysis (Evolution) and Commonality Induction."
            }
        });

        return response.text || "Failed to extract recipe.";
    });
};

export const generateImage = async (prompt: string, styleSuffix: string, ratio: string, artisticScale: number = 1.0, resolution: string = '1K', spatial?: SpatialConfig, recipeInstruction?: string): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const spatialTxt = getSpatialInstructions(spatial);
        const recipePart = recipeInstruction ? `\n\n[PRIORITY DESIGN RECIPE]: ${recipeInstruction}` : "";
        const fullPrompt = `${prompt}. ${spatialTxt} ${recipePart}. Style: ${styleSuffix}. Creative intensity: ${artisticScale}`;
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{ parts: [{ text: fullPrompt }] }],
            config: {
                imageConfig: {
                    aspectRatio: normalizeAspectRatio(ratio)
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("No image data generated.");
    });
};

export const generateWithReferences = async (prompt: string, refs: {label: string, base64: string}[], ratio: string, styleSuffix: string, artisticScale: number = 1.0, resolution: string = '1K', spatial?: SpatialConfig, recipeInstruction?: string, inferenceConfig?: InferenceSettings): Promise<string> => {
    return retryWithBackoff(async () => {
        await ensureApiKey();
        const ai = getAI();
        const parts: any[] = [];
        refs.forEach(r => {
            const data = r.base64.split(',')[1] || r.base64;
            const mimeType = r.base64.split(';')[0].split(':')[1] || 'image/jpeg';
            parts.push({ inlineData: { data, mimeType } });
            parts.push({ text: `REFERENCE VOLUME [${r.label}]: Analyze this image for strict geometric massing. PRESERVE THE VOLUMETRIC BOUNDARIES.` });
        });

        const spatialTxt = getSpatialInstructions(spatial);
        const recipePart = recipeInstruction ? `\n\n[GLOBAL DESIGN STYLE RECIPE]: ${recipeInstruction}` : "";

        let finalActionPrompt = prompt;
        if (inferenceConfig) {
            finalActionPrompt = getVolumeInferenceInstructions(inferenceConfig.influence, inferenceConfig.prompt, inferenceConfig.subjectType);
        }

        parts.push({ text: `CHARACTER CONSISTENCY COMMAND: Perform a spatial transformation of the reference subject. \nTARGET VIEW: ${spatialTxt}. ${recipePart} \nACTION: ${finalActionPrompt}. \nIMPORTANT: Maintain the exact breed/type/nature of the subject from the reference.` });

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: [{ parts }],
            config: {
                imageConfig: {
                    aspectRatio: (normalizeAspectRatio(ratio) as any),
                    imageSize: (resolution as any)
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error(response.text || "No image generated.");
    });
};

export const editImage = async (sourceBase64: string, prompt: string, ratio: string, maskBase64?: string): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const parts: any[] = [];

        // Part 1: Source
        const sData = sourceBase64.split(',')[1] || sourceBase64;
        const sMime = sourceBase64.split(';')[0].split(':')[1] || 'image/jpeg';
        parts.push({ inlineData: { data: sData, mimeType: sMime } });
        parts.push({ text: "[SOURCE IMAGE]: This is the original design to be edited." });

        // Part 2: Mask (if provided)
        if (maskBase64) {
            const mData = maskBase64.split(',')[1] || maskBase64;
            const mMime = maskBase64.split(';')[0].split(':')[1] || 'image/png';
            parts.push({ inlineData: { data: mData, mimeType: mMime } });
            parts.push({ text: "[MASK IMAGE]: This image defines the surgical area for editing. White or non-transparent pixels indicate the region to be modified. Everything outside this region MUST remain identical to the [SOURCE IMAGE]." });
        }

        const systemCommand = maskBase64 
            ? `SURGICAL INPAINTING PROTOCOL: Use the [MASK IMAGE] as an absolute spatial boundary. Modify the specified region in the [SOURCE IMAGE] to match this instruction: "${prompt}". Focus on G2 Curvature and industrial design logic. DO NOT alter any pixels outside the masked region.`
            : `SURGICAL EDIT: ${prompt}. KEEP ALL OTHER STRUCTURES UNCHANGED.`;

        parts.push({ text: systemCommand });

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: [{ parts }],
            config: {
                imageConfig: {
                    aspectRatio: normalizeAspectRatio(ratio)
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Failed to edit image.");
    });
};

export const generateVideo = async (prompt: string): Promise<string> => {
    return retryWithBackoff(async () => {
        await ensureApiKey();
        const ai = getAI();
        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt: `Cinematic visualization: ${prompt}.`,
            config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
        });

        while (!operation.done) {
            await sleep(10000);
            operation = await ai.operations.getVideosOperation({ operation: operation });
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        return URL.createObjectURL(blob);
    });
};

