  // 记忆化演化强度：默认 Detailing (60%)
  const [currentEvolutionLevel, setCurrentEvolutionLevel] = useState(60);

  // Design Recipe Extraction State
  const [extractedRecipe, setExtractedRecipe] = useState<{instruction: string, images: string[]} | null>(null);
  const [isExtractingRecipe, setIsExtractingRecipe] = useState(false);
  const [isSavingRecipe, setIsSavingRecipe] = useState(false);
  const [availableRecipes, setAvailableRecipes] = useState<DesignRecipe[]>([]);

  const [recordingStatus, setRecordingStatus] = useState<'idle' | 'recording' | 'paused'>('idle');
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  const canvasRef = useRef<CanvasRef>(null);
  const chatRef = useRef<GeminiChatPanelRef>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const saveTimeoutRef = useRef<number | null>(null);

  const pasteCountRef = useRef(0);
  const lastPasteTimeRef = useRef(0);

  const selectedItem = selection.length === 1 ? items.find(it => it.id === selection[0]) || null : null;

  const centerOnItem = useCallback((item: CanvasItem, targetScale?: number) => {
    const scale = targetScale || Math.min(view.scale, 1.0);
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth;
    const centerX = leftPanelWidth + availableWidth / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (item.x + item.width / 2) * scale, y: centerY - (item.y + item.height / 2) * scale });
  }, [view.scale, showLayers, showHistory, isPropertiesPanelOpen]);

  const zoomToFit = useCallback(() => {
    if (items.length === 0) {
        setView({ x: 0, y: 0, scale: 1 });
        return;
    }
    const minX = Math.min(...items.map(i => i.x));
    const minY = Math.min(...items.map(i => i.y));
    const maxX = Math.max(...items.map(i => i.x + i.width));
    const maxY = Math.max(...items.map(i => i.y + i.height));
    const contentWidth = maxX - minX;
    const contentHeight = maxY - minY;
    const padding = 100;
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth - padding * 2;
    const availableHeight = window.innerHeight - padding * 2;
    const scale = Math.min(availableWidth / contentWidth, availableHeight / contentHeight, 1.5);
    const centerX = leftPanelWidth + (window.innerWidth - leftPanelWidth - rightPanelWidth) / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (minX + contentWidth / 2) * scale, y: centerY - (minY + contentHeight / 2) * scale });
  }, [items, showLayers, showHistory, isPropertiesPanelOpen]);

  /**
   * Recraft 风格排列算法：
   * 1. 优先保持 Y 轴一致（水平对齐）。
   * 2. 只有在右侧无限探测都被占用的情况下才尝试下方。
   */
  const findPlacementSpot = useCallback((width: number, height: number, itemsList: CanvasItem[], relativeTo?: CanvasItem, offsetIdx: number = 0) => {
    const spacing = 80; 

    if (itemsList.length === 0) {
        return { 
          x: (window.innerWidth / 2 - view.x) / view.scale - width / 2, 
          y: (window.innerHeight / 2 - view.y) / view.scale - height / 2 
        };
    }

    const ref = relativeTo || itemsList[itemsList.length - 1];
    let startX = ref.x + ref.width + spacing;
    let startY = ref.y; // 核心：默认 Y 轴对齐，不再斜向偏移

    const isOccupied = (tx: number, ty: number) => {
        return itemsList.some(it => {
            const overlapX = tx < it.x + it.width + 10 && tx + width + 10 > it.x;
            const overlapY = ty < it.y + it.height + 10 && ty + height + 10 > it.y;
            return overlapX && overlapY;
        });
    };

    let curX = startX + (offsetIdx * (width / 4));
    let curY = startY;
    let attempts = 0;

    // 向右持续探测空白
    while (isOccupied(curX, curY) && attempts < 50) {
        curX += spacing;
        attempts++;
    }

    // 如果向右探测太远（>5000px），则尝试换行
    if (attempts >= 50) {
        curX = ref.x;
        curY = ref.y + ref.height + spacing;
        attempts = 0;
        while (isOccupied(curX, curY) && attempts < 50) {
            curY += spacing;
            attempts++;
        }
    }

    return { x: curX, y: curY };
  }, [view.x, view.y, view.scale]);

  const handleFile = useCallback(async (file: File, x?: number, y?: number) => {
    const reader = new FileReader();
    reader.onload = async (event) => {
        const content = event.target?.result as string;
        const isVideo = file.type.startsWith('video/') || file.name.endsWith('.webm');
        const { width, height } = isVideo ? await getVideoDimensions(content) : await getImageDimensions(content);
        const displayWidth = 500;
        const displayHeight = (height * displayWidth) / width;

        setItems(prev => {
            let targetPos;
            if (x !== undefined && y !== undefined) {
                targetPos = { 
                  x: (x - view.x) / view.scale - displayWidth / 2, 
                  y: (y - view.y) / view.scale - displayHeight / 2 
                };
            } else {
                targetPos = findPlacementSpot(displayWidth, displayHeight, prev);
            }

            const newItem: CanvasItem = { 
              id: crypto.randomUUID(), 
              type: isVideo ? ItemType.VIDEO : ItemType.IMAGE, 
              x: targetPos.x, 
              y: targetPos.y, 
              width: displayWidth, 
              height: displayHeight, 
              rotation: 0, 
              content: content, 
              status: 'generated', 
              prompt: file.name, 
              aspectRatio: getClosestAspectRatio(width, height) 
            };
            setSelection([newItem.id]);
            return [...prev, newItem];
        });
    };
    reader.readAsDataURL(file);
  }, [view.x, view.y, view.scale, findPlacementSpot]);

  const handleCopy = useCallback((e: ClipboardEvent | null) => {
    if (e) {
      const target = e.target as HTMLElement;
      if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;
      const selectionText = window.getSelection()?.toString();
      if (selectionText && selectionText.length > 0) return;
    }
    if (selection.length === 0) return;
    const selectedItems = items.filter(it => selection.includes(it.id));
    const data = JSON.stringify(selectedItems);
    if (e) e.clipboardData?.setData('application/json/recreate-items', data);
    localStorage.setItem('recreate_clipboard', data);
    if (e) e.preventDefault();
  }, [selection, items]);

  const handlePaste = useCallback(async (e: ClipboardEvent) => {
    const target = e.target as HTMLElement;
    const tagName = target.tagName?.toUpperCase();
    if (tagName === 'INPUT' || tagName === 'TEXTAREA' || target.isContentEditable) return;

    let dataStr = e.clipboardData?.getData('application/json/recreate-items');
    if (!dataStr) {
      dataStr = localStorage.getItem('recreate_clipboard') || '';
    }

    if (dataStr) {
      try {
        const itemsToPaste = JSON.parse(dataStr) as CanvasItem[];
        if (itemsToPaste.length > 0) {
          e.preventDefault();
          const now = Date.now();
          if (now - lastPasteTimeRef.current > 2000) {
            pasteCountRef.current = 1;
          } else {
            pasteCountRef.current += 1;
          }
          lastPasteTimeRef.current = now;
          const offset = pasteCountRef.current * 24;

          const newItems = itemsToPaste.map(it => ({
            ...it,
            id: crypto.randomUUID(),
            x: it.x + offset,
            y: it.y + offset,
            status: 'generated' as const
          }));

          setItems(prev => [...prev, ...newItems]);
          setSelection(newItems.map(it => it.id));
          return;
        }
      } catch (err) {
        console.error("Paste parse error:", err);
      }
    }

    const clipboardItems = e.clipboardData?.items;
    if (!clipboardItems) return;
    for (let i = 0; i < clipboardItems.length; i++) {
        if (clipboardItems[i].type.indexOf("image") !== -1 || clipboardItems[i].type.indexOf("video") !== -1) {
            const file = clipboardItems[i].getAsFile();
            if (file) {
              e.preventDefault();
              handleFile(file);
            }
        }
    }
  }, [handleFile]);

  useEffect(() => {
    const handleDrop = (e: DragEvent) => {
        e.preventDefault();
        const files = Array.from(e.dataTransfer?.files || []);
        files.forEach(file => {
            if (file.type.startsWith('image/') || file.type.startsWith('video/') || file.name.endsWith('.webm')) {
                handleFile(file, e.clientX, e.clientY);
            }
        });
    };
    const handleDragOver = (e: DragEvent) => e.preventDefault();

    window.addEventListener('copy', handleCopy as any);
    window.addEventListener('paste', handlePaste);
    window.addEventListener('drop', handleDrop);
    window.addEventListener('dragover', handleDragOver);
    return () => {
        window.removeEventListener('copy', handleCopy as any);
        window.removeEventListener('paste', handlePaste);
        window.removeEventListener('drop', handleDrop);
        window.removeEventListener('dragover', handleDragOver);
    };
  }, [handleCopy, handlePaste, handleFile]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;

      if (e.key === 'Delete' || e.key === 'Backspace') {
        if (selection.length > 0) handleDeleteItems(selection);
      }
      if (e.key === ' ') {
        e.preventDefault();
        if (quickLookItem) setQuickLookItem(null);
        else if (selectedItem) setQuickLookItem(selectedItem);
      }
      if (e.key === 'Escape') { 
          setQuickLookItem(null); 
          if (editMode) setEditMode(false); 
          if (isPickingPoint) setIsPickingPoint(false);
          setExpressionState({ itemId: '', isOpen: false });
          setInferenceState({ itemId: '', isOpen: false });
          setTool('select');
      }
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.preventDefault();
        if (quickLookItem) {
            const assetItems = items.filter(it => (it.type === ItemType.IMAGE || it.type === ItemType.VIDEO) && it.content);
            if (assetItems.length > 0) {
                const currentIndex = assetItems.findIndex(it => it.id === quickLookItem.id);
                let nextIndex = currentIndex;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') nextIndex = (currentIndex + 1) % assetItems.length;
                else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') nextIndex = (currentIndex - 1 + assetItems.length) % assetItems.length;
                const nextItem = assetItems[nextIndex];
                setQuickLookItem(nextItem);
                setSelection([nextItem.id]);
                centerOnItem(nextItem);
            }
        } else if (selection.length > 0) {
            const step = e.shiftKey ? 10 : 1;
            const updates = selection.map(id => {
              const item = items.find(i => i.id === id);
              if (!item) return null;
              let nx = item.x, ny = item.y;
              if (e.key === 'ArrowUp') ny -= step;
              if (e.key === 'ArrowDown') ny += step;
              if (e.key === 'ArrowLeft') nx -= step;
              if (e.key === 'ArrowRight') nx += step;
              return { id, updates: { x: nx, y: ny } };
            }).filter(Boolean) as { id: string, updates: Partial<CanvasItem> }[];
            if (updates.length > 0) handleUpdateItems(updates);
        }
      }
      if (e.key.toLowerCase() === 'v') setTool('select');
      if (e.key.toLowerCase() === 'h') setTool('hand');
      if (e.key.toLowerCase() === 'r') setTool('point');
      if (e.key.toLowerCase() === 'c') setTool('capture');
      if (e.key.toLowerCase() === 'g') setShowGrid(prev => !prev);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selection, items, selectedItem, quickLookItem, editMode, view.scale, showLayers, showHistory, centerOnItem, isPickingPoint]);

  const startRecording = async (resolution: string) => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: { cursor: "always" } as any, audio: false });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.ondataavailable = (event) => { if (event.data.size > 0) recordedChunksRef.current.push(event.data); };
      mediaRecorder.onstop = () => {
        const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `Recraft-${new Date().getTime()}.webm`;
        a.click();
        setRecordingStatus('idle'); setRecordingTime(0);
        if (timerRef.current) window.clearInterval(timerRef.current);
      };
      mediaRecorder.start();
      setRecordingStatus('recording');
      timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch (err) { console.error(err); }
  };

