export const identifyPoint = async (base64: string, y: number, x: number): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `观察归一化坐标 [y=${Math.round(y)}, x=${Math.round(x)}]。请仅返回该处的视觉特征中文名称，控制在 6 字以内。` }
                ]
            }]
        });
        return response.text?.trim() || "选定点位";
    });
};

export const detectAllPoints = async (base64: string, temperature: number = 0.8): Promise<{point: [number, number], label: string}[]> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `识别图中所有关键视觉特征.
必须包含以下两个层级的特征：
1. 主体大特征 (Major Subject Areas): 识别并标注整个主体。
2. 细节特征 (Detail Features): 识别具体的纹理、面部、关键关节等细节。
为每个特征提供中心位置 [y, x] 坐标 (0-1000).
仅返回一个 JSON 数组，每个对象包含 'point' (坐标数组 [y, x]) 和专业的中文描述 'label'.` }
                ]
            }],
            config: { 
                responseMimeType: "application/json",
                temperature: temperature,
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            point: { 
                                type: Type.ARRAY,
                                items: { type: Type.NUMBER }
                            },
                            label: { type: Type.STRING }
                        },
                        required: ["point", "label"]
                    }
                }
            }
        });
        return JSON.parse(response.text);
    });
};

export const analyzeImageForPrompt = async (base64: string): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
