                        <img src={img} className="w-full h-full object-cover" />
                        <button type="button" onClick={() => removeRefImage(i)} className="absolute inset-0 bg-red-600/80 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 backdrop-blur-sm">
                            <XIcon className="w-3.5 h-3.5" />
                        </button>
                    </div>
                ))}
             </div>

             <textarea 
                autoFocus
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder={selectedRecipeId ? `正在应用食谱: ${activeRecipe?.name}...` : "在此输入您的创意生成指令..."}
                className="flex-1 bg-transparent text-[16px] font-bold text-zinc-900 placeholder-zinc-300 py-3 focus:outline-none resize-none h-[48px] leading-snug transition-all no-scrollbar pr-16"
                onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        handleSubmit();
                    }
                }}
             />
        </div>

        <div className="flex items-center justify-between px-4 pb-2.5 pt-2 border-t border-zinc-50/60 mt-1">
            <div className="flex items-center gap-2">
                 <button type="button" onClick={() => { setShowRecipes(!showRecipes); setShowStyles(false); setShowRatios(false); setShowResolution(false); }} className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.1em] transition-all shadow-sm ${selectedRecipeId ? 'bg-indigo-600 text-white shadow-xl' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'}`}>
