                 <button type="button" onClick={() => { setShowStyles(!showStyles); setShowRatios(false); setShowResolution(false); setShowRecipes(false); }} className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.1em] transition-all shadow-sm ${showStyles ? 'bg-indigo-600 text-white shadow-xl' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'}`}>
                   {selectedStyle.label}
                </button>
                 <button type="button" onClick={() => { setShowRatios(!showRatios); setShowStyles(false); setShowResolution(false); setShowRecipes(false); }} className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.1em] transition-all shadow-sm ${showRatios ? 'bg-indigo-600 text-white shadow-xl' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'}`}>
                   {selectedRatio.id}
                </button>
            </div>
            <div className="flex items-center gap-3 pr-0.5">
                 <button type="button" onClick={() => { setShowResolution(!showResolution); setShowRatios(false); setShowStyles(false); setShowRecipes(false); }} className="flex items-center justify-center bg-zinc-100/80 rounded-[12px] px-3.5 py-2 text-[10px] font-black text-zinc-500 transition-all hover:bg-zinc-200 uppercase tracking-widest border border-zinc-200/20 shadow-sm">
                    {selectedResolution}
                 </button>
                 <button type="button" onClick={() => { setShowAdvanced(!showAdvanced); setShowRecipes(false); }} className={`w-10 h-10 flex items-center justify-center rounded-[14px] transition-all duration-300 ${showAdvanced ? 'text-indigo-600 bg-indigo-50 shadow-inner' : 'text-zinc-400 hover:text-zinc-700'}`}>
                    <SettingsIcon className={`w-5 h-5 transition-transform ${showAdvanced ? 'rotate-90' : ''}`} />
                 </button>
                 <button type="button" onClick={() => handleSubmit()} disabled={!prompt.trim() && refImages.length === 0} className={`w-10 h-10 flex items-center justify-center rounded-[16px] transition-all duration-500 ${ (prompt.trim() || refImages.length > 0) ? 'bg-[#09090b] text-white hover:scale-110 active:scale-95 shadow-[0_12px_32px_rgba(0,0,0,0.25)]' : 'bg-zinc-100 text-zinc-300 cursor-not-allowed opacity-50'}`}>
                    <ArrowIcon className="w-6 h-6" />
                 </button>
            </div>
        </div>
      </form>
    </div>
  );
};

export default BottomBar;

