                        <button onClick={() => onJSONAnalysis?.(selectedItem.id)} disabled={isAnalyzingJSON} className={`w-full py-4 border border-indigo-500/20 rounded-xl flex items-center justify-center gap-3 text-indigo-400 text-[11px] font-black uppercase tracking-[0.2em] transition-all hover:bg-indigo-600/10 ${isAnalyzingJSON ? 'opacity-50 cursor-wait' : ''}`}>
