                 {segments.length === 0 && (
                    <div className="p-6 bg-[#09090b] border-t border-zinc-800/50 shrink-0">
                        <button onClick={() => onApplyEdit?.(editPrompt)} disabled={!editPrompt.trim()} className="w-full py-4 bg-indigo-600 disabled:bg-zinc-800/50 disabled:text-zinc-700 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.2em] text-[11px] rounded-[16px] shadow-xl transition-all flex items-center justify-center gap-3"><SparklesIcon className="w-4 h-4"/> 应用重绘</button>
                    </div>
