                 <div className="flex items-center p-6 border-b border-zinc-800 bg-[#09090b] shrink-0"><button onClick={handleBack} className="w-9 h-9 flex items-center justify-center hover:bg-zinc-800 rounded-xl mr-3 transition-all text-zinc-400 hover:text-white"><ChevronLeftIcon className="w-4 h-4"/></button><span className="text-[11px] font-black uppercase tracking-[0.2em] text-zinc-100">{currentView === 'adjust_colors' ? '调色' : '背景'}</span></div>
                 <div className="flex-1 flex flex-col items-center justify-center p-10 opacity-40"><PaletteIcon className="w-12 h-12 text-zinc-700 mb-4" /><p className="text-zinc-600 text-[11px] font-black uppercase tracking-[0.2em]">模块开发中</p></div>
              </div>
