const getClosestAspectRatio = (width: number, height: number): string => {
  const ratio = width / height;
  const targets = [ { id: '1:1', val: 1 }, { id: '16:9', val: 16 / 9 }, { id: '9:16', val: 9 / 16 }, { id: '4:3', val: 4 / 3 }, { id: '3:4', val: 3 / 4 } ];
  return targets.reduce((prev, curr) => Math.abs(curr.val - ratio) < Math.abs(prev.val - ratio) ? curr : prev ).id;
};

const getImageDimensions = (src: string): Promise<{ width: number; height: number }> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve({ width: img.naturalWidth, height: img.naturalHeight });
    img.onerror = () => resolve({ width: 512, height: 512 });
    img.src = src;
  });
};

const getVideoDimensions = (src: string): Promise<{ width: number; height: number }> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.onloadedmetadata = () => resolve({ width: video.videoWidth, height: video.videoHeight });
      video.onerror = () => resolve({ width: 640, height: 360 });
      video.src = src;
    });
};

