        if (quickLookItem) {
            const assetItems = items.filter(it => (it.type === ItemType.IMAGE || it.type === ItemType.VIDEO) && it.content);
            if (assetItems.length > 0) {
                const cur = quickLookItem;
                const curCX = cur.x + cur.width / 2;
                const curCY = cur.y + cur.height / 2;

                let candidates = assetItems.filter(it => it.id !== cur.id);
                if (e.key === 'ArrowRight') candidates = candidates.filter(it => (it.x + it.width / 2) > curCX);
                else if (e.key === 'ArrowLeft') candidates = candidates.filter(it => (it.x + it.width / 2) < curCX);
                else if (e.key === 'ArrowUp') candidates = candidates.filter(it => (it.y + it.height / 2) < curCY);
                else if (e.key === 'ArrowDown') candidates = candidates.filter(it => (it.y + it.height / 2) > curCY);

                if (candidates.length > 0) {
                    const next = candidates.reduce((prev, curr) => {
                        const dc = Math.abs((curr.x + curr.width/2) - curCX) + Math.abs((curr.y + curr.height/2) - curCY) * 2;
                        const dp = Math.abs((prev.x + prev.width/2) - curCX) + Math.abs((prev.y + prev.height/2) - curCY) * 2;
