                    <span className="text-[12px] font-black uppercase tracking-[0.2em] text-zinc-100 flex-1">局部重绘</span>
                    <button onClick={handleBack} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-zinc-800 text-zinc-500"><XIcon className="w-4 h-4" /></button>
                 </div>

                 <div className="flex-1 overflow-y-auto no-scrollbar p-6 space-y-8">
                    <div className="grid grid-cols-4 gap-2 bg-[#111113] p-1.5 rounded-2xl border border-zinc-800">
                        {[
                        { id: 'lasso', icon: <LassoIcon className="w-4 h-4" />, label: '套索' },
                        { id: 'brush', icon: <BrushIcon className="w-4 h-4" />, label: '画笔' },
