                        ))}
                    </div>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.15em]">笔触大小</label><span className="text-zinc-400 font-mono text-[11px] font-black">{brushSize}px</span></div>
                        <input type="range" min="1" max="150" step="1" value={brushSize} onChange={(e) => setBrushSize?.(Number(e.target.value))} className="w-full h-1 bg-zinc-800 rounded-lg appearance-none accent-indigo-500 cursor-pointer" />
                    </div>
                    <div className="space-y-4">
