                let candidates = assetItems.filter(it => it.id !== cur.id);
                if (e.key === 'ArrowRight') candidates = candidates.filter(it => (it.x + it.width / 2) > curCX);
                else if (e.key === 'ArrowLeft') candidates = candidates.filter(it => (it.x + it.width / 2) < curCX);
