import React, { useState, useRef, useEffect, useMemo } from 'react';
import { XIcon, SparklesIcon, ChevronDownIcon, WandIcon, BoxIcon, EvolutionIcon, CreativeScaleIcon } from './Icons';
import { CanvasItem } from '../types';
import { EVOLUTION_STAGES, getEvolutionStage } from '../services/evolutionService';

interface ExpressionControllerProps {
  item: CanvasItem;
  view: { x: number; y: number; scale: number };
  onClose: () => void;
  onGenerate: (expressionOrLevel: string) => void;
  initialEvolutionLevel?: number;
}

const EMOTIONS = [
  { id: 'angry', label: 'Angry', emoji: '😠', prompt: 'an angry and furious facial expression, intense gaze' },
  { id: 'sad', label: 'Sad', emoji: '😢', prompt: 'a sad and melancholic facial expression, downcast eyes' },
  { id: 'indifferent', label: 'Indifferent', emoji: '😐', prompt: 'an indifferent and neutral facial expression, blank state' },
  { id: 'happy', label: 'Happy', emoji: '😊', prompt: 'a happy and joyful facial expression, warm smile' },
  { id: 'silly', label: 'Silly', emoji: '😜', prompt: 'a silly and playful facial expression, sticking tongue out, funny look' },
  { id: 'curious', label: 'Curious', emoji: '🤔', prompt: 'a curious and inquisitive facial expression, raised eyebrow, tilted head' },
  { id: 'infatuated', label: 'Infatuated', emoji: '😍', prompt: 'an infatuated and loving facial expression, heart eyes vibe, soft look' },
  { id: 'excited', label: 'Excited', emoji: '🤩', prompt: 'an extremely excited and enthusiastic facial expression, energetic eyes, big smile' },
];

const ExpressionController: React.FC<ExpressionControllerProps> = ({ item, view, onClose, onGenerate, initialEvolutionLevel = 60 }) => {
  const [mode, setMode] = useState<'expression' | 'evolution'>('evolution');
  const [selectedIndex, setSelectedIndex] = useState(3); // 情感模式索引 (0-7)
  const [localEvolutionLevel, setLocalEvolutionLevel] = useState(initialEvolutionLevel); // 演化模式百分比 (0-100)
  const [isDragging, setIsDragging] = useState(false);
  const sliderRef = useRef<HTMLDivElement>(null);

  // Map centralized stages to UI with icons
  const idStagesWithIcons = useMemo(() => [
    { ...EVOLUTION_STAGES[0], icon: <WandIcon className="w-8 h-8 text-indigo-400" /> },
    { ...EVOLUTION_STAGES[1], icon: <CreativeScaleIcon className="w-8 h-8 text-indigo-400" /> },
    { ...EVOLUTION_STAGES[2], icon: <BoxIcon className="w-8 h-8 text-indigo-400" /> },
    { ...EVOLUTION_STAGES[3], icon: <EvolutionIcon className="w-8 h-8 text-indigo-400" /> },
  ], []);

  useEffect(() => {
    setLocalEvolutionLevel(initialEvolutionLevel);
  }, [initialEvolutionLevel]);

  // 计算控制器在画布上的绝对位置
  const top = (item.y * view.scale + view.y) + (item.height * view.scale / 2) - 160;
  const left = (item.x + item.width) * view.scale + view.x + 40;

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    updateValue(e);
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (isDragging) updateValue(e);
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  const updateValue = (e: React.MouseEvent | MouseEvent) => {
    if (!sliderRef.current) return;
    const rect = sliderRef.current.getBoundingClientRect();

    // 弧形的圆心坐标
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + (110 / 130) * rect.height; 

    const dx = e.clientX - centerX;
    const dy = e.clientY - centerY;

    // 计算角度并归一化到 0-1
    let angle = Math.atan2(dy, dx);
    let normalized = (angle + Math.PI) / Math.PI;
    normalized = Math.max(0, Math.min(1, normalized));

    if (mode === 'expression') {
      const newIndex = Math.round(normalized * (EMOTIONS.length - 1));
      setSelectedIndex(newIndex);
    } else {
      const newLevel = Math.round(normalized * 100);
      setLocalEvolutionLevel(newLevel);
    }
  };

  const handleGenerate = () => {
    if (mode === 'expression') {
      onGenerate(EMOTIONS[selectedIndex].prompt);
    } else {
      onGenerate(localEvolutionLevel.toString());
    }
  };

  const getPointOnArc = (percent: number) => {
    const angle = (percent / 100) * Math.PI - Math.PI;
    const radius = 100;
    return {
      x: Math.cos(angle) * radius + 110,
      y: Math.sin(angle) * radius + 110
    };
  };

  const handleToggleMode = () => {
    setMode(mode === 'expression' ? 'evolution' : 'expression');
  };

  const currentStage = getEvolutionStage(localEvolutionLevel);
  // Re-attach UI icon for the central feedback area
  const currentStageWithIcon = idStagesWithIcons.find(s => s.id === currentStage.id) || idStagesWithIcons[0];

  const handlePercent = mode === 'expression' ? (selectedIndex / (EMOTIONS.length - 1)) * 100 : localEvolutionLevel;
  const currentPos = getPointOnArc(handlePercent);

  return (
    <div 
      className="fixed z-[200] bg-[#0c0c0e]/95 backdrop-blur-3xl border border-white/10 p-6 rounded-[32px] shadow-[0_40px_100px_rgba(0,0,0,0.8)] animate-in zoom-in-95 duration-300 pointer-events-auto flex flex-col items-center gap-6 select-none w-[280px]"
      style={{ top, left }}
      onMouseDown={e => e.stopPropagation()}
    >
      <div className="w-full flex items-center justify-between mb-2">
        <button 
          onClick={handleToggleMode}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'evolution' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'bg-white/5 text-zinc-400 hover:bg-white/10'}`}
        >
          {mode === 'expression' ? '情感/表达调节' : '工业智能演化 (ID)'}
          <ChevronDownIcon className="w-3 h-3" />
        </button>
        <button onClick={onClose} className="p-2 text-zinc-500 hover:text-white transition-colors">
          <XIcon className="w-4 h-4" />
        </button>
      </div>

      <div className="relative w-[220px] h-[130px] flex items-end justify-center overflow-visible" ref={sliderRef} onMouseDown={handleMouseDown}>
         <svg className="absolute inset-0 overflow-visible" viewBox="0 0 220 130">
            <path d="M 10 110 A 100 100 0 0 1 210 110" fill="none" stroke="white" strokeWidth="2" strokeOpacity="0.05" strokeLinecap="round" />
            <path d={`M 10 110 A 100 100 0 0 1 ${currentPos.x} ${currentPos.y}`} fill="none" stroke={mode === 'evolution' ? "#8b80ff" : "#5546fe"} strokeWidth="4" strokeLinecap="round" className={isDragging ? "" : "transition-all duration-300"} />

            {mode === 'expression' && EMOTIONS.map((_, i) => {
                const p = getPointOnArc((i / (EMOTIONS.length - 1)) * 100);
                const isActive = selectedIndex === i;
                return (
                    <circle key={i} cx={p.x} cy={p.y} r={isActive ? 4 : 2} fill={isActive ? "#5546fe" : "white"} fillOpacity={isActive ? 1 : 0.2} className="transition-all duration-300" />
                );
            })}

            <circle cx={currentPos.x} cy={currentPos.y} r="8" fill={mode === 'evolution' ? "#8b80ff" : "#5546fe"} className={`shadow-2xl ${isDragging ? "" : "transition-all duration-300"}`} style={{ filter: 'drop-shadow(0 0 8px rgba(139, 128, 255, 0.5))' }} />
            <circle cx={currentPos.x} cy={currentPos.y} r="3" fill="white" className={isDragging ? "" : "transition-all duration-300"} />
         </svg>

         <div className="flex flex-col items-center gap-3 animate-in fade-in duration-500 mb-2">
             <div className="w-16 h-16 rounded-[24px] bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center shadow-inner overflow-hidden relative">
                {mode === 'expression' ? (
                   <span className="text-4xl animate-in zoom-in duration-300" key={EMOTIONS[selectedIndex].emoji}>{EMOTIONS[selectedIndex].emoji}</span>
                ) : (
                   <div className="flex flex-col items-center gap-0.5 animate-in zoom-in duration-300" key={currentStage.id}>{currentStageWithIcon.icon}</div>
                )}
             </div>
             <div className="flex flex-col items-center min-h-[32px]">
                <span className="text-white font-black text-[11px] uppercase tracking-[0.2em] text-center">
                    {mode === 'expression' ? EMOTIONS[selectedIndex].label : currentStage.label}
                </span>
                {mode === 'evolution' && (
                  <span className="text-indigo-400 font-mono text-[10px] font-black mt-0.5 animate-in fade-in">
                    {localEvolutionLevel}% STRENGTH
                  </span>
                )}
             </div>
         </div>
      </div>

      <button onClick={handleGenerate} className={`w-full py-4 rounded-[20px] font-black text-[12px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 group ${mode === 'evolution' ? 'bg-indigo-600 hover:bg-indigo-500 text-white' : 'bg-[#5546fe] hover:bg-[#6366f1] text-white'}`} >
        <SparklesIcon className="w-4 h-4 group-hover:rotate-12 transition-transform" />
        {mode === 'evolution' ? '执行精确演化' : '立即重绘表情'}
      </button>

      <div className="w-full flex justify-between items-center text-[8px] font-black text-zinc-700 uppercase tracking-widest px-2">
         <span>{mode === 'expression' ? 'Angry' : 'Polish'}</span>
         <span>{mode === 'expression' ? 'Excited' : 'Radical'}</span>
      </div>
    </div>
  );
};

export default ExpressionController;

import { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import React from 'react';
import { EditToolType } from '../types';

interface MaskCanvasProps {
  width: number;
  height: number;
  imageSrc: string;
  tool: EditToolType;
  brushColor?: string;
  brushSize?: number;
  isTextMode?: boolean;
  // Added onApplyEdit to the props interface to match usage in Canvas.tsx
  onApplyEdit?: (prompt: string) => void;
}

export interface MaskCanvasRef {
  getSelectionMask: () => Promise<string | null>;
  getMaskedImage: () => Promise<string | null>;
  clearMask: () => void;
  undo: () => void;
}

const MaskCanvas = forwardRef<MaskCanvasRef, MaskCanvasProps>(({ 
  width, height, imageSrc, tool, brushColor = '#ef4444', brushSize = 12, isTextMode, onApplyEdit 
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [history, setHistory] = useState<ImageData[]>([]);
  const [pendingTextPos, setPendingTextPos] = useState<{ x: number, y: number } | null>(null);
  const [textInput, setTextInput] = useState('');
  const [mousePos, setMousePos] = useState<{ x: number, y: number } | null>(null);
  const textInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (canvas) {
      canvas.width = 1024;
      canvas.height = 1024;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (ctx) {
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
      }
    }
  }, []);

  const saveHistory = () => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && canvas) {
      const currentData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      setHistory(prev => [...prev, currentData].slice(-20));
    }
  };

  useImperativeHandle(ref, () => ({
    undo: () => {
      const canvas = canvasRef.current;
      const ctx = canvas?.getContext('2d');
      if (!ctx || !canvas) return;

      setHistory(prev => {
        if (prev.length === 0) {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          return [];
        }
        const newHistory = [...prev];
        const prevState = newHistory.pop();
        if (prevState) {
          ctx.putImageData(prevState, 0, 0);
        } else {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
        return newHistory;
      });
    },
    clearMask: () => {
      const ctx = canvasRef.current?.getContext('2d');
      if (ctx) ctx.clearRect(0, 0, 1024, 1024);
      setHistory([]);
    },
    getSelectionMask: async () => {
      const maskCanvas = canvasRef.current;
      if (!maskCanvas) return null;

      // 创建工业标准的黑白掩码：黑色背景，白色代表修改区域
      const outputCanvas = document.createElement('canvas');
      outputCanvas.width = 1024;
      outputCanvas.height = 1024;
      const outCtx = outputCanvas.getContext('2d');
      if (!outCtx) return null;

      // 1. 填充纯黑背景（代表锁定区域）
      outCtx.fillStyle = 'black';
      outCtx.fillRect(0, 0, 1024, 1024);

      // 2. 将涂鸦层转换为纯白色（代表修改区域）
      // 使用 brightness(0) invert(1) 滤镜将任何颜色的涂鸦转为纯白
      outCtx.filter = 'brightness(0) invert(1)';
      outCtx.drawImage(maskCanvas, 0, 0);
      outCtx.filter = 'none';

      return outputCanvas.toDataURL('image/png');
    },
    getMaskedImage: async () => {
        const maskCanvas = canvasRef.current;
        if (!maskCanvas) return null;

        return new Promise((resolve) => {
            const img = new Image();
            img.crossOrigin = "anonymous";
            img.onload = () => {
                const outputCanvas = document.createElement('canvas');
                outputCanvas.width = 1024;
                outputCanvas.height = 1024;
                const outCtx = outputCanvas.getContext('2d');
                if (!outCtx) { resolve(null); return; }

                outCtx.drawImage(img, 0, 0, 1024, 1024);
                outCtx.globalCompositeOperation = 'destination-in';
                outCtx.drawImage(maskCanvas, 0, 0);
                resolve(outputCanvas.toDataURL('image/png'));
            };
            img.onerror = () => resolve(null);
            img.src = imageSrc;
        });
    }
  }));

  const getPos = (e: React.MouseEvent) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return { x: 0, y: 0 };
    return {
      x: (e.clientX - rect.left) * (1024 / rect.width),
      y: (e.clientY - rect.top) * (1024 / rect.height)
    };
  };

  const drawTextTag = (ctx: CanvasRenderingContext2D, text: string, x: number, y: number) => {
    const fontSize = 56;
    ctx.font = `bold ${fontSize}px Inter, sans-serif`;

    ctx.save();

    // Draw white marker dot with heavy shadow
    ctx.fillStyle = 'white';
    ctx.shadowColor = 'rgba(0,0,0,1)';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(x, y, 8, 0, Math.PI * 2);
    ctx.fill();

    // High-contrast text: White with thick black stroke (no red fill box as requested)
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'center';

    // Outer black stroke for visibility on light backgrounds
    ctx.strokeStyle = 'rgba(0,0,0,0.9)';
    ctx.lineWidth = 10;
    ctx.strokeText(text, x, y - (fontSize + 10));

    // Inner white fill
    ctx.fillStyle = 'white';
    ctx.fillText(text, x, y - (fontSize + 10));

    ctx.restore();
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return;
    const p = getPos(e);

    if (isTextMode) {
      setPendingTextPos(p);
      setTextInput('');
      setTimeout(() => textInputRef.current?.focus(), 50);
      return;
    }

    saveHistory();
    setIsDrawing(true);
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx) return;

    ctx.globalCompositeOperation = tool === 'eraser' ? 'destination-out' : 'source-over';
    ctx.strokeStyle = brushColor;
    ctx.lineWidth = brushSize * (1024 / (width || 1));

    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const p = getPos(e);
    setMousePos(p);

    if (!isDrawing || isTextMode) return;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx) return;

    ctx.lineTo(p.x, p.y);
    ctx.stroke();
  };

  const handleMouseUp = () => {
    if (isDrawing) {
      const canvas = canvasRef.current;
      const ctx = canvas?.getContext('2d');
      if (ctx) ctx.closePath();
      setIsDrawing(false);
    }
  };

  const handleFinishTextInput = () => {
    if (pendingTextPos && textInput.trim()) {
      saveHistory();
      const canvas = canvasRef.current;
      const ctx = canvas?.getContext('2d');
      if (ctx) {
        ctx.globalCompositeOperation = 'source-over';
        drawTextTag(ctx, textInput.trim(), pendingTextPos.x, pendingTextPos.y);
      }
    }
    setPendingTextPos(null);
  };

  return (
    <div className="absolute inset-0 z-50 pointer-events-none overflow-hidden" onMouseLeave={() => setMousePos(null)}>
      <canvas 
        ref={canvasRef} 
        onMouseDown={handleMouseDown} 
        onMouseMove={handleMouseMove} 
        onMouseUp={handleMouseUp} 
        className={`absolute inset-0 pointer-events-auto ${isTextMode ? 'cursor-crosshair bg-white/5' : 'cursor-none touch-none'}`} 
        style={{ width: '100%', height: '100%' }}
      />

      {/* 笔触预览圆圈 */}
      {!isTextMode && mousePos && (
        <div 
            className="absolute border border-white/50 bg-white/20 rounded-full pointer-events-none z-[60] shadow-[0_0_10px_rgba(0,0,0,0.5)]"
            style={{ 
                left: `${(mousePos.x / 1024) * 100}%`, 
                top: `${(mousePos.y / 1024) * 100}%`,
                width: `${(brushSize * (1024 / (width || 1)) / 1024) * 100}%`,
                height: `${(brushSize * (1024 / (width || 1)) / 1024) * 100}%`,
                transform: 'translate(-50%, -50%)',
                borderColor: tool === 'eraser' ? '#ffffff80' : `${brushColor}80`,
                backgroundColor: tool === 'eraser' ? '#ffffff20' : `${brushColor}20`
            }}
        />
      )}

      {pendingTextPos && (
        <div 
          className="absolute z-[100] pointer-events-auto"
          style={{ 
            left: `${(pendingTextPos.x / 1024) * 100}%`, 
            top: `${(pendingTextPos.y / 1024) * 100}%`,
            transform: 'translate(-50%, -120%)'
          }}
        >
          <div className="bg-zinc-900 border border-indigo-500 rounded-xl p-3 shadow-2xl flex items-center gap-3 min-w-[200px] animate-in slide-in-from-bottom-2">
            <input 
              ref={textInputRef}
              type="text"
              value={textInput}
              onChange={(e) => setTextInput(e.target.value)}
              onBlur={handleFinishTextInput}
              onKeyDown={(e) => e.key === 'Enter' && handleFinishTextInput()}
              className="bg-zinc-800 border-none rounded-lg px-3 py-1.5 text-xs text-white outline-none focus:ring-1 focus:ring-indigo-500 flex-1"
              placeholder="输入修改指令..."
            />
            <button onClick={handleFinishTextInput} className="bg-indigo-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest">确认</button>
          </div>
        </div>
      )}
    </div>
  );
});

