const CORE_PROTOCOL = "CORE PROTOCOL: Maintain the ABSOLUTE camera perspective and spatial orientation of the reference image. The evolved object MUST occupy the exact same 3D bounding box. DO NOT rotate the object.";

/**
 * 工业设计演化阶梯定义 (ID Evolution Ladder)
