/**
 * 根据强度等级 (0-100) 获取当前的演化阶段数据
 */
export const getEvolutionStage = (level: number): EvolutionStage => {
  return EVOLUTION_STAGES.find(s => level >= s.min && level <= s.max) || EVOLUTION_STAGES[0];
};

/**
 * 生成最终发给图像生成模型的演化指令串
