export const getEvolutionDirective = (level: number, basePrompt: string): string => {
  const stage = getEvolutionStage(level);
  return `ID EVOLUTION MANDATE (Target Level: ${level}% - Phase: ${stage.label}):
${stage.directive}
${CORE_PROTOCOL}
Contextual Product Context: ${basePrompt}.
Style Context: High-end industrial design product photography, studio light.`;
};

