  inferenceState: { itemId: string, isOpen: boolean };
  setInferenceState: (state: { itemId: string, isOpen: boolean }) => void;
  currentEvolutionLevel?: number;
}

export interface CanvasRef { 
    getMaskData: () => Promise<{ cutout: string, mask: string } | null>;
    clearMask: () => void;
}

const SNAP_THRESHOLD = 10;

interface TransformingState {
  type: 'resize' | 'rotate' | 'drag';
  handle?: string;
  startX: number;
  startY: number;
  initialItems: {
    id: string;
    x: number;
    y: number;
    w: number;
    h: number;
    r: number;
  }[];
}

interface DraggingPointState {
    itemId: string;
    pointId: string;
    startX: number;
    startY: number;
    startPoint: [number, number]; // [y, x]
}

const Canvas = forwardRef<CanvasRef, CanvasProps>(({ 
  items, selection, tool, view, setView, setSelection, addItem, updateItem, updateItems,
  onContextMenu, editMode, editTool = 'brush', brushSize = 30, brushColor = '#6366f1',
  onApplyEdit, onSelectItem, onPointPicked, isPickingPoint, onPointTagClick,
  showPointLabels = true, onDeletePoint, onDeletePointLocal, onMovePoint, onMovePointEnd, isTextMode,
  showGrid = true, onZoomToFit, onCaptureRegion, onFloatingAction,
  expressionState, setExpressionState, inferenceState, setInferenceState, currentEvolutionLevel = 60
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const maskCanvasRef = useRef<MaskCanvasRef>(null);
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState<Point>({ x: 0, y: 0 });
  const [isMarquee, setIsMarquee] = useState(false);
  const [marqueeStart, setMarqueeStart] = useState<Point>({ x: 0, y: 0 });
  const [marqueeEnd, setMarqueeEnd] = useState<Point>({ x: 0, y: 0 });

  const [isCapturing, setIsCapturing] = useState(false);
  const [captureStart, setCaptureStart] = useState<Point | null>(null);
  const [captureRect, setCaptureRect] = useState<Rect | null>(null);
  const [showCaptureMenu, setShowCaptureMenu] = useState(false);

  // Annotation states
  const [annotations, setAnnotations] = useState<Annotation[]>([]);
  const [activeAnnotationTool, setActiveAnnotationTool] = useState<'none' | 'arrow' | 'text' | 'number' | 'eraser' | 'rectangle' | 'circle' | 'brush'>('none');
  const [annotationColor, setAnnotationColor] = useState('#ef4444');
  const [isDrawingAnnotation, setIsDrawingAnnotation] = useState(false);
  const [activeAnnotationId, setActiveAnnotationId] = useState<string | null>(null);
  const [annotationTextInput, setAnnotationTextInput] = useState<{ id: string, x: number, y: number, value: string } | null>(null);
  const annotationTextInputRef = useRef<HTMLInputElement>(null);

  const [transforming, setTransforming] = useState<TransformingState | null>(null);
  const [draggingPoint, setDraggingPoint] = useState<DraggingPointState | null>(null);
  const [mouseCanvasPos, setMouseCanvasPos] = useState<Point>({ x: 0, y: 0 });

  const [snapLines, setSnapLines] = useState<{ x?: number, y?: number }[]>([]);
  const [spacePressed, setSpacePressed] = useState(false);
  const lastMiddleClickRef = useRef<number>(0);

  const [textInput, setTextInput] = useState<{ x: number, y: number, value: string } | null>(null);
  const textInputRef = useRef<HTMLTextAreaElement>(null);

  const [hoveredPointId, setHoveredPointId] = useState<string | null>(null);
  const hoverTimeoutRef = useRef<number | null>(null);

  const isInteracting = isPanning || !!transforming || isMarquee || !!draggingPoint || isCapturing || isDrawingAnnotation;

  const annotationColors = [
    { id: 'red', value: '#ef4444' },
    { id: 'yellow', value: '#facc15' },
    { id: 'green', value: '#22c55e' },
    { id: 'blue', value: '#3b82f6' },
    { id: 'white', value: '#ffffff' },
  ];

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === ' ' && !['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName)) {
            setSpacePressed(true);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        if (e.key === ' ') setSpacePressed(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
        window.removeEventListener('keydown', handleKeyDown);
        window.removeEventListener('keyup', handleKeyUp);
        if (hoverTimeoutRef.current) window.clearTimeout(hoverTimeoutRef.current);
    };
  }, []);

  const clearHoverTimeout = () => {
      if (hoverTimeoutRef.current) {
          window.clearTimeout(hoverTimeoutRef.current);
          hoverTimeoutRef.current = null;
      }
  };

  const setHoveredPointWithDelay = (id: string | null) => {
      clearHoverTimeout();
      if (id === null) {
          hoverTimeoutRef.current = window.setTimeout(() => {
              setHoveredPointId(null);
          }, 300);
      } else {
          setHoveredPointWithDelay(null); // Clear previous if any
          setHoveredPointId(id);
      }
  };

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const handleWheelNative = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        const factor = Math.pow(1.1, -e.deltaY / 100);
        const newScale = Math.max(0.05, Math.min(10, view.scale * factor));
        const rect = el.getBoundingClientRect();
        const mx = e.clientX - rect.left, my = e.clientY - rect.top;
        setView({ x: mx - (mx - view.x) * (newScale / view.scale), y: my - (my - view.y) * (newScale / view.scale), scale: newScale });
      } else {
        setView({ ...view, x: view.x - e.deltaX, y: view.y - e.deltaY });
      }
    };
    el.addEventListener('wheel', handleWheelNative, { passive: false });
    return () => el.removeEventListener('wheel', handleWheelNative);
  }, [view, setView]);

  useImperativeHandle(ref, () => ({ 
    getMaskData: async () => {
        if (!maskCanvasRef.current) return null;
        const cutout = await maskCanvasRef.current.getMaskedImage();
        const mask = await maskCanvasRef.current.getSelectionMask();
        if (!cutout || !mask) return null;
        return { cutout, mask };
    },
    clearMask: () => maskCanvasRef.current?.clearMask()
  }));

  const screenToCanvas = (sx: number, sy: number) => {
    const rect = containerRef.current!.getBoundingClientRect();
    return { x: (sx - rect.left - view.x) / view.scale, y: (sy - rect.top - view.y) / view.scale };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY);

    if (e.button === 1) {
        e.preventDefault();
        const now = Date.now();
        if (now - lastMiddleClickRef.current < 300) {
            onZoomToFit?.();
            setIsPanning(false);
            lastMiddleClickRef.current = 0;
            return;
        }
        lastMiddleClickRef.current = now;
        setIsPanning(true);
        setPanStart({ x: e.clientX - view.x, y: e.clientY - view.y });
        return;
    }

    if (tool === 'hand' || spacePressed) {
      const target = e.target as HTMLElement;
      if (target.closest('.point-trigger')) return; 
      e.preventDefault();
      setIsPanning(true);
      setPanStart({ x: e.clientX - view.x, y: e.clientY - view.y });
      return;
    }

    if (tool === 'capture') {
        if (showCaptureMenu && activeAnnotationTool !== 'none') {
            if (captureRect && pos.x >= captureRect.x && pos.x <= captureRect.x + captureRect.width && pos.y >= captureRect.y && pos.y <= captureRect.y + captureRect.height) {
                if (activeAnnotationTool === 'number') {
                    const nextNum = annotations.filter(a => a.type === 'number').length + 1;
                    const newAnno: Annotation = {
                        id: crypto.randomUUID(),
                        type: 'number',
                        points: [pos],
                        text: nextNum.toString(),
                        color: annotationColor,
                        size: 24
                    };
                    setAnnotations(prev => [...prev, newAnno]);
                } else if (activeAnnotationTool === 'text') {
                    const id = crypto.randomUUID();
                    setAnnotationTextInput({ id, x: pos.x, y: pos.y, value: '' });
                    setTimeout(() => annotationTextInputRef.current?.focus(), 50);
                } else if (activeAnnotationTool === 'arrow' || activeAnnotationTool === 'rectangle' || activeAnnotationTool === 'circle' || activeAnnotationTool === 'brush') {
                    setIsDrawingAnnotation(true);
                    const id = crypto.randomUUID();
                    setActiveAnnotationId(id);
                    setAnnotations(prev => [...prev, { 
                        id, 
                        type: activeAnnotationTool as any, 
                        points: activeAnnotationTool === 'brush' ? [pos] : [pos, pos], 
                        color: annotationColor, 
                        size: 4 
                    }]);
                }
                return;
            }
        }
        setShowCaptureMenu(false);
        setAnnotations([]);
        setIsCapturing(true);
        setCaptureStart(pos);
        setCaptureRect(null);
        return;
    }

    if (tool === 'text' && !editMode) {
      setTextInput({ x: pos.x, y: pos.y, value: '' });
      setTimeout(() => textInputRef.current?.focus(), 50);
      return;
    }

    if (editMode) return; 
    const target = e.target as HTMLElement;
    const isBg = target.id === 'canvas-bg' || target.id === 'dot-grid';
    if (isBg && tool === 'select' && e.button === 0) {
      setIsMarquee(true);
      setMarqueeStart(pos);
      setMarqueeEnd(pos);
      if (!e.shiftKey) setSelection([]);
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY);
    setMouseCanvasPos(pos);

    if (draggingPoint) {
        const item = items.find(i => i.id === draggingPoint.itemId);
        if (item) {
            const nx = Math.min(1000, Math.max(0, ((pos.x - item.x) / item.width) * 1000));
            const ny = Math.min(1000, Math.max(0, ((pos.y - item.y) / item.height) * 1000));
            onMovePoint?.(item.id, draggingPoint.pointId, ny, nx);
        }
        return;
    }

    if (isPanning) {
      setView({ ...view, x: e.clientX - panStart.x, y: e.clientY - panStart.y });
    } else if (isCapturing && captureStart) {
        setCaptureRect({
            x: Math.min(captureStart.x, pos.x),
            y: Math.min(captureStart.y, pos.y),
            width: Math.abs(captureStart.x - pos.x),
            height: Math.abs(captureStart.y - pos.y)
        });
    } else if (isDrawingAnnotation && activeAnnotationId) {
        setAnnotations(prev => prev.map(a => {
            if (a.id === activeAnnotationId) {
                if (a.type === 'brush') {
                    return { ...a, points: [...a.points, pos] };
                } else {
                    return { ...a, points: [a.points[0], pos] };
                }
            }
            return a;
        }));
    } else if (isMarquee) {
      setMarqueeEnd(pos);
      const x1 = Math.min(marqueeStart.x, pos.x), y1 = Math.min(marqueeStart.y, pos.y);
      const x2 = Math.max(marqueeStart.x, pos.x), y2 = Math.max(marqueeStart.y, pos.y);
      setSelection(items.filter(i => i.x >= x1 && i.x + i.width <= x2 && i.y >= y1 && i.y + i.height <= y2).map(i => i.id));
    } else if (transforming) {
      if (transforming.type === 'drag') {
          let dx = pos.x - transforming.startX;
          let dy = pos.y - transforming.startY;
          const activeSnapLines: {x?: number, y?: number}[] = [];
          const primaryItem = transforming.initialItems[0];
          let nx = primaryItem.x + dx;
          let ny = primaryItem.y + dy;
          items.forEach(other => {
            const isOtherInTransform = transforming.initialItems.some(i => i.id === other.id);
            if (isOtherInTransform) return;
            const otherEdgesX = [other.x, other.x + other.width, other.x + other.width / 2];
            const otherEdgesY = [other.y, other.y + other.height, other.y + other.height / 2];
            const itemEdgesX = [nx, nx + primaryItem.w, nx + primaryItem.w / 2];
            const itemEdgesY = [ny, ny + primaryItem.h, ny + primaryItem.h / 2];
            itemEdgesX.forEach((ix) => {
              otherEdgesX.forEach(ox => {
                if (Math.abs(ix - ox) < SNAP_THRESHOLD) { dx += ox - ix; nx += ox - ix; activeSnapLines.push({ x: ox }); }
              });
            });
            itemEdgesY.forEach((iy) => {
              otherEdgesY.forEach(oy => {
                if (Math.abs(iy - oy) < SNAP_THRESHOLD) { dy += oy - iy; ny += oy - iy; activeSnapLines.push({ y: oy }); }
              });
            });
          });
          setSnapLines(activeSnapLines);
          const updates = transforming.initialItems.map(init => ({ id: init.id, x: init.x + dx, y: init.y + dy }));
          updates.forEach(u => updateItem(u.id, { x: u.x, y: u.y }));
      } else if (transforming.type === 'resize') {
          const dx = pos.x - transforming.startX;
          const dy = pos.y - transforming.startY;
          const targetInit = transforming.initialItems[0];
          const item = items.find(i => i.id === targetInit.id)!;
          let newW = targetInit.w, newH = targetInit.h, newX = targetInit.x, newY = targetInit.y;
          const handle = transforming.handle!;
          if (handle.includes('right')) newW += dx;
          if (handle.includes('left')) { newW -= dx; newX += dx; }
          if (handle.includes('bottom')) newH += dy;
          if (handle.includes('top')) { newH -= dy; newY += dy; }
          if (item.type === ItemType.IMAGE || item.type === ItemType.VIDEO) { const aspect = targetInit.w / targetInit.h; if (Math.abs(dx) > Math.abs(dy)) newH = newW / aspect; else newW = newH * aspect; }
          updateItem(item.id, { width: Math.max(20, newW), height: Math.max(20, newH), x: newX, y: newY });
      } else if (transforming.type === 'rotate') {
          const targetInit = transforming.initialItems[0];
          const centerX = targetInit.x + targetInit.w / 2, centerY = targetInit.y + targetInit.h / 2;
          const angle = Math.atan2(pos.y - centerY, pos.x - centerX) * (180 / Math.PI) + 90;
          updateItem(targetInit.id, { rotation: angle });
      }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => { 
      if (draggingPoint) {
          const pos = screenToCanvas(e.clientX, e.clientY);
          const item = items.find(i => i.id === draggingPoint.itemId);
          if (item) {
              const nx = Math.min(1000, Math.max(0, ((pos.x - item.x) / item.width) * 1000));
              const ny = Math.min(1000, Math.max(0, ((pos.y - item.y) / item.height) * 1000));
              if (Math.abs(draggingPoint.startPoint[0] - ny) > 1 || Math.abs(draggingPoint.startPoint[1] - nx) > 1) {
                  onMovePointEnd?.(item.id, draggingPoint.pointId, draggingPoint.startPoint, [ny, nx]);
              }
          }
      }

      if (isCapturing) {
          setIsCapturing(false);
          if (captureRect && captureRect.width > 5 && captureRect.height > 5) {
              setShowCaptureMenu(true);
          } else {
              setCaptureRect(null);
          }
      }

      if (isDrawingAnnotation) {
          setIsDrawingAnnotation(false);
          setActiveAnnotationId(null);
      }

      setIsPanning(false); 
      setIsMarquee(false); 
      setTransforming(null); 
      setDraggingPoint(null);
      setSnapLines([]); 
  };

  const handleAnnotationTextConfirm = () => {
    if (annotationTextInput && annotationTextInput.value.trim()) {
        const newAnno: Annotation = {
            id: annotationTextInput.id,
            type: 'text',
            points: [{ x: annotationTextInput.x, y: annotationTextInput.y }],
            text: annotationTextInput.value,
            color: annotationColor,
            size: 20
        };
        setAnnotations(prev => [...prev, newAnno]);
    }
    setAnnotationTextInput(null);
  };

  const sortedItems = useMemo(() => [...items].sort((a, b) => {
      if (a.type === ItemType.FRAME && b.type !== ItemType.FRAME) return -1;
      if (a.type !== ItemType.FRAME && b.type === ItemType.FRAME) return 1;
      return 0;
  }), [items]);

  const handleFinishTextInput = () => {
    if (textInput && textInput.value.trim()) {
      const newItem: CanvasItem = {
        id: crypto.randomUUID(),
        type: ItemType.TEXT,
        x: textInput.x,
        y: textInput.y,
        width: 300,
        height: 60,
        rotation: 0,
        content: textInput.value,
        status: 'generated'
      };
      addItem(newItem);
      setSelection([newItem.id]);
    }
    setTextInput(null);
  };

  const handleScale = Math.max(0.1, 1 / view.scale);
  const handleSize = 14 * handleScale;
  const borderWidth = 2 * handleScale;
  const rotateHandleSize = 40 * handleScale;
  const rotateHandleOffset = 64 * handleScale;
  const rotateIconSize = 20 * handleScale;

  const selectedItems = items.filter(i => selection.includes(i.id));

  return (
    <div 
        ref={containerRef} 
        onMouseDown={handleMouseDown} 
        onMouseMove={handleMouseMove} 
        onMouseUp={handleMouseUp} 
        onContextMenu={e => { e.preventDefault(); onContextMenu?.(e); }} 
        id="canvas-bg" 
        className={`relative w-full h-full overflow-hidden select-none bg-[#f4f4f5] dark:bg-[#09090b] ${spacePressed || isPanning ? 'cursor-grabbing' : (tool === 'hand' ? 'cursor-grab' : '')} ${isPickingPoint || tool === 'point' || tool === 'capture' ? 'cursor-crosshair' : ''} ${tool === 'text' ? 'cursor-text' : ''}`}
    >
      {showGrid && (
        <div id="dot-grid" className={`absolute inset-0 pointer-events-none ${!isInteracting ? 'transition-all duration-[600ms] cubic-bezier(0.2, 0.0, 0, 1)' : ''}`} style={{ backgroundSize: `${20*view.scale}px ${20*view.scale}px`, backgroundPosition: `${view.x}px ${view.y}px`, backgroundImage: `radial-gradient(circle, #27272a 0.5px, transparent 0.5px)` }} />
      )}

      <div className={`origin-top-left absolute ${!isInteracting ? 'transition-transform duration-[600ms] cubic-bezier(0.2, 0.0, 0, 1)' : 'transition-none'}`} style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})` }}>
        {sortedItems.map(item => {
          const isSel = selection.includes(item.id);
          const isFrame = item.type === ItemType.FRAME;
          const isBeingEdited = editMode && isSel;
          const isBeingTransformed = transforming?.initialItems.some(ti => ti.id === item.id);
          const hasPoints = item.identifiedPoints && item.identifiedPoints.length > 0;

          return (
            <div 
                key={item.id} 
                data-item-id={item.id}
                className={`absolute group ${isSel ? 'z-50' : (isFrame ? 'z-0' : 'z-10')} ${isBeingTransformed ? 'pointer-events-none' : ''}`} 
                style={{ left: item.x, top: item.y, width: item.width, height: item.height, transform: `rotate(${item.rotation || 0}deg)`, opacity: isBeingTransformed ? 0.6 : 1, transition: 'opacity 0.2s ease-in-out' }} 
                onDoubleClick={() => !isPickingPoint && onSelectItem?.(item.id)}
                onContextMenu={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    onContextMenu?.(e, item.id);
                }}
            >
              {isFrame && <div className="absolute -top-7 left-0 px-2.5 py-1 bg-indigo-500 text-white text-[10px] font-black uppercase rounded-t-lg shadow-sm whitespace-nowrap" style={{ transform: `scale(${handleScale})`, transformOrigin: 'bottom left', marginBottom: `${4*handleScale}px` }}>{item.content || 'Frame'}</div>}

              {item.inferenceInfluence !== undefined && (
                <div 
                    className="absolute top-4 right-4 bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/10 z-[60] flex items-center gap-2 animate-in fade-in zoom-in"
                    style={{ transform: `scale(${handleScale})`, transformOrigin: 'top right' }}
                >
                    <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 shadow-[0_0_8px_indigo]" />
                    <span className="text-[10px] font-black text-white uppercase tracking-widest">Influence: {Math.round(item.inferenceInfluence * 100)}%</span>
                </div>
              )}

              <div 
                onMouseDown={e => { 
                    if (e.button !== 0 || editMode) return; 
                    if (isPickingPoint || tool === 'point') {
                        e.stopPropagation();
                        const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                        const relX = (e.clientX - rect.left) / (rect.width || 1);
                        const relY = (e.clientY - rect.top) / (rect.height || 1);
                        if (relX >= 0 && relX <= 1 && relY >= 0 && relY <= 1) { onPointPicked?.(item.id, relY * 1000, relX * 1000); }
                        return;
                    }
                    if (tool === 'select') { 
                        e.stopPropagation(); 
                        const newSelection = e.shiftKey ? [...selection, item.id] : (selection.includes(item.id) ? selection : [item.id]); 
                        setSelection(newSelection); 
                        const initialItems = newSelection.map(id => { const it = items.find(i => i.id === id)!; return { id: it.id, x: it.x, y: it.y, w: it.width, h: it.height, r: it.rotation || 0 }; }); 
                        setTransforming({ type: 'drag', startX: mouseCanvasPos.x, startY: mouseCanvasPos.y, initialItems }); 
                    } 
                }} 
                className={`w-full h-full relative ${ (isBeingEdited || (showPointLabels && hasPoints)) ? 'overflow-visible' : 'overflow-hidden'} rounded-xl transition-all ${ isFrame ? 'bg-white/5 dark:bg-zinc-800/5' : 'bg-zinc-900/50' } ${isBeingTransformed && isFrame ? 'bg-transparent border-dashed border-indigo-400' : ''}`} 
                style={{
                    borderWidth: isSel ? `${borderWidth}px` : (isFrame ? `${1*handleScale}px` : 0),
                    borderColor: isSel ? '#3b82f6' : (isFrame ? '#3f3f46' : 'transparent'),
                    boxShadow: isSel ? `0 0 ${30*handleScale}px rgba(59,130,246,0.3)` : 'none'
                }}
              >
                {item.type === ItemType.IMAGE && (item.content ? <img src={item.content} className="w-full h-full object-contain pointer-events-none" /> : (
                  <div className="w-full h-full flex flex-col items-center justify-center bg-zinc-900/95 relative overflow-hidden mesh-gradient-bg">
                    {item.status === 'loading' ? (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="shimmer-line" />
                        <div className="relative w-32 h-32 flex items-center justify-center">
                             <div className="ai-ring" style={{ animationDelay: '0s' }} />
                             <div className="ai-ring" style={{ animationDelay: '0.5s' }} />
                             <div className="ai-ring" style={{ animationDelay: '1s' }} />
                             <div className="relative z-10 flex flex-col items-center gap-6 animate-in zoom-in duration-1000">
                                  <div className="w-16 h-16 rounded-[24px] bg-white/5 border border-white/10 flex items-center justify-center shadow-2xl backdrop-blur-md">
                                       <SparklesIcon className="w-8 h-8 text-indigo-400" style={{ animation: 'rotation-slow 4s linear infinite' }} />
                                  </div>
                                  <div className="flex flex-col items-center gap-2">
                                       <span className="text-[10px] font-black text-white uppercase tracking-[0.4em] drop-shadow-lg">AI 正在构思</span>
                                       <div className="flex gap-1">
                                            {[0, 1, 2].map(i => (
                                                <div key={i} className="w-1 h-1 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: `${i*0.2}s` }} />
                                            ))}
                                       </div>
                                  </div>
                             </div>
                        </div>
                      </div>
                    ) : (
                      <ImageIcon className="w-8 h-8 opacity-10" />
                    )}
                  </div>
                ))}
                {item.type === ItemType.VIDEO && (
                    item.content ? (
                        <video 
                            src={item.content} 
                            controls 
                            loop 
                            muted 
                            className="w-full h-full object-contain"
                        />
                    ) : null
                )}
                {item.type === ItemType.TEXT && (
                  <div className="w-full h-full flex items-center justify-center p-4">
                    <p className="text-zinc-800 dark:text-zinc-100 font-bold text-center leading-tight whitespace-pre-wrap select-none" style={{ fontSize: `${item.height * 0.4}px` }}>
                      {item.content || 'Add text...'}
                    </p>
                  </div>
                )}
                {/* FIX: Removed onApplyEdit as it is not defined in MaskCanvasProps */}
                {isBeingEdited && ( <MaskCanvas ref={maskCanvasRef} width={item.width} height={item.height} imageSrc={item.content} tool={editTool} brushColor={brushColor} brushSize={brushSize} isTextMode={isTextMode} /> )}

                {!isBeingEdited && showPointLabels && item.identifiedPoints && item.identifiedPoints.map((pt, idx) => {
                    const px = (pt.x / 1000) * item.width;
                    const py = (pt.y / 1000) * item.height;
                    const isHovered = hoveredPointId === pt.id;
                    const isBeingDragged = draggingPoint?.pointId === pt.id;

                    return (
                        <div 
                            key={pt.id} 
                            className="absolute z-[120] pointer-events-auto" 
                            style={{ left: px, top: py }}
                            onMouseEnter={() => setHoveredPointWithDelay(pt.id)}
                            onMouseLeave={() => setHoveredPointWithDelay(null)}
                            onContextMenu={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                setDraggingPoint(null);
                                onDeletePointLocal?.(item.id, pt.id);
                            }}
                        >
                             <div 
                                onMouseDown={(e) => { 
                                    if (e.button !== 0) return; 
                                    e.stopPropagation(); 
                                    e.preventDefault(); 
                                    setDraggingPoint({ itemId: item.id, pointId: pt.id, startX: e.clientX, startY: e.clientY, startPoint: [pt.y, pt.x] }); 
                                }} 
                                className="point-trigger absolute -translate-x-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center cursor-grab active:cursor-grabbing z-[140]"
                             >
                                 <div 
                                    className={`rounded-full border border-white shadow-[0_4px_12px_rgba(0,0,0,0.5)] flex items-center justify-center transition-all ${isHovered || isBeingDragged ? 'bg-indigo-600 scale-110' : 'bg-[#5546fe]'}`}
                                    style={{
                                        width: `${24*handleScale}px`,
                                        height: `${24*handleScale}px`,
                                        borderWidth: `${2*handleScale}px`
                                    }}
                                 >
                                    <span className="font-black text-white select-none" style={{ fontSize: `${10*handleScale}px` }}>{pt.label}</span>
                                 </div>
                             </div>

                             {isHovered && !isBeingDragged && (
                                <div 
                                    className="absolute top-0 left-0 pt-3 pl-3 transition-all animate-in zoom-in-95 duration-200 flex flex-col items-start z-[1000] pointer-events-auto origin-top-left" 
                                    style={{ transform: `scale(${handleScale})` }}
                                    onMouseEnter={clearHoverTimeout}
                                    onClick={e => e.stopPropagation()} 
                                    onMouseDown={e => e.stopPropagation()}
                                >
                                    <div className="absolute -top-4 -left-4 w-12 h-12 bg-transparent pointer-events-auto z-[-1]" />

                                    <div className="bg-[#0c0c0e]/95 backdrop-blur-3xl shadow-[0_32px_80px_rgba(0,0,0,0.9)] rounded-[20px] border border-white/10 p-0 flex flex-col min-w-[220px] overflow-hidden ring-1 ring-white/5">
                                        <div className="flex items-center justify-between px-4 py-3.5 gap-3 bg-zinc-900/40">
                                            <div className="flex items-center gap-2.5 overflow-hidden">
                                                <div className="w-2.5 h-2.5 rounded-full bg-[#5546fe] shadow-[0_0_10px_rgba(85,70,254,1)] animate-pulse" />
                                                <span className="text-[14px] font-bold text-white tracking-wide truncate max-w-[140px] drop-shadow-sm">{pt.description || `特征点 ${pt.label}`}</span>
                                            </div>
                                            <button 
                                                onClick={(e) => { 
                                                  e.stopPropagation(); 
                                                  onDeletePoint?.(item.id, pt.id); 
                                                }} 
                                                className="p-1.5 hover:bg-red-500/10 rounded-lg transition-all group/del active:scale-90"
                                            > 
                                                <TrashIcon className="w-4 h-4 text-zinc-600 group-hover/del:text-red-500" /> 
                                            </button>
                                        </div>

                                        <div className="h-px bg-white/5 w-full" />

                                        <div className="p-3">
                                            <button 
                                                onClick={(e) => { 
                                                    e.stopPropagation(); 
                                                    onPointTagClick?.(item, pt); 
                                                    setHoveredPointId(null);
                                                }}
                                                className="w-full text-[12px] font-black uppercase tracking-[0.15em] text-white flex items-center justify-center gap-2.5 py-4 px-4 bg-[#5546fe] hover:bg-indigo-500 rounded-xl transition-all shadow-[0_10px_25px_rgba(85,70,254,0.3)] active:scale-[0.96] group/btn border border-white/5"
                                            >
                                                <SparklesIcon className="w-4 h-4 group-hover/btn:rotate-12 transition-transform" />
                                                作为空间参考
                                            </button>
                                        </div>
                                    </div>
                                </div>
                             )}
                        </div>
                    );
                })}
              </div>

              {isSel && !editMode && !isBeingTransformed && !isPickingPoint && tool !== 'point' && tool !== 'capture' && ( 
                <> 
                    {['top-left', 'top-right', 'bottom-left', 'bottom-right', 'top', 'bottom', 'left', 'right'].map(h => ( 
                        <div 
                            key={h} 
                            onMouseDown={e => { if (e.button !== 0) return; e.stopPropagation(); setTransforming({ type: 'resize', handle: h, startX: mouseCanvasPos.x, startY: mouseCanvasPos.y, initialItems: [{ id: item.id, x: item.x, y: item.y, w: item.width, h: item.height, r: item.rotation || 0 }] }); }} 
                            className={`absolute bg-white z-[90] shadow-xl rounded-full cursor-${h.includes('left') || h.includes('right') ? (h.includes('top') ? 'nw' : 'sw') + '-resize' : h.includes('top') ? 'n-resize' : 'w-resize'} hover:scale-125 transition-transform`} 
                            style={{
                                width: `${handleSize}px`,
                                height: `${handleSize}px`,
                                borderWidth: `${borderWidth}px`,
