  }, [selection, items, selectedItem, quickLookItem, editMode, view.scale, showLayers, showHistory, centerOnItem, isPickingPoint]);

  const startRecording = async (resolution: string) => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: { cursor: "always" } as any, audio: false }); streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream); mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.ondataavailable = (event) => { if (event.data.size > 0) recordedChunksRef.current.push(event.data); };
      mediaRecorder.onstop = () => { const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `Recraft-${new Date().getTime()}.webm`; a.click(); setRecordingStatus('idle'); setRecordingTime(0); if (timerRef.current) window.clearInterval(timerRef.current); };
      mediaRecorder.start(); setRecordingStatus('recording'); timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch (err) {}
  };
  const stopRecording = () => { mediaRecorderRef.current?.stop(); streamRef.current?.getTracks().forEach(track => track.stop()); };

  useEffect(() => { const initLoad = async () => { const snapshots = await getAllSnapshots(); if (snapshots.length > 0) setItems(snapshots[0].items); const recipes = await getAllRecipes(); setAvailableRecipes(recipes); }; initLoad(); }, []);
  useEffect(() => {
    if (items.length === 0) return;
