    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative">
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => { const spot = findPlacementSpot(800, 600, items); const f: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: spot.x, y: spot.y, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' }; setItems(p => [...p, f]); setSelection([f.id]); }} recordingStatus={recordingStatus} onStartRecording={startRecording} onStopRecording={stopRecording} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={recordingTime} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection.length > 0 ? selection[0] : null} onSelectItem={(id) => { setSelection([id]); const item = items.find(i => i.id === id); if (item) centerOnItem(item); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => setItems(snap.items)} />
      <div className="w-full h-full">
        <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={it => setItems(p => [...p, it])} updateItem={handleUpdateItem} updateItems={handleUpdateItems} onContextMenu={(e, id) => { if (tool === 'point' || tool === 'capture') { setTool('select'); return; } setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId: id }); }} onDelete={id => handleDeleteItems([id])} editMode={editMode} editTool={editTool} brushSize={brushSize} brushColor={brushColor} segments={segments} onApplyEdit={handleApplyEdit} onSelectItem={(id) => { const item = items.find(it => id === it.id); if (item && (item.type === ItemType.IMAGE || item.type === ItemType.VIDEO) && item.content) { if (isPickingPoint && pickingTargetId === item.id) return; if (tool === 'point' || tool === 'capture') return; setQuickLookItem(item); } }} onPointPicked={handlePickPoint} isPickingPoint={isPickingPoint && !!pickingTargetId} onPointTagClick={(it, pt) => chatRef.current?.addPointReference(it.id, it.content || '', pt.label, [pt.y, pt.x])} showPointLabels={showPointLabels} onDeletePoint={(iid, pid) => setItems(prev => prev.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it))} onDeletePointLocal={(iid, pid) => setItems(prev => prev.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it))} onMovePoint={(iid, pid, ny, nx) => setItems(prev => prev.map(item => item.id === iid ? { ...item, identifiedPoints: item.identifiedPoints?.map(p => p.id === pid ? { ...p, y: ny, x: nx } : p) } : item))} onMovePointEnd={(iid, pid, from, to) => { const item = items.find(i => i.id === iid); if (item?.content) { const point = item.identifiedPoints?.find(p => p.id === pid); if (point) chatRef.current?.appendMovementDescription(iid, item.content, point.label, from, to); } }} isTextMode={editSubMode === 'text'} showGrid={showGrid} onZoomTo