           <div className="relative h-full">
             {isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(false)} className="absolute top-4 right-4 z-[50] w-9 h-9 rounded-xl flex items-center justify-center bg-white/10 hover:bg-white/20 text-white transition-all border border-white/10 shadow-lg"><XIcon className="w-4 h-4" /></button>}
             <PropertiesPanel selectedItem={selectedItem} onUpdateItem={handleUpdateItem} onGenerate={handleGenerate} onDelete={id => handleDeleteItems([id])} onAutoPrompt={id => analyzeImageForPrompt(items.find(it => it.id === id)?.content || '').then(p => handleUpdateItem(id, { prompt: p }))} onSendToPrompt={id => { const item = items.find(i => i.id === id); if (item?.content) setExternalRefImage(item.content); }} onSendToGemini={id => { const item = items.find(i => i.id === id); if (item?.content) chatRef.current?.addExternalAttachment(item.id, item.content); }} onSyncPointsToGemini={handleSyncPointsToGemini} onEnterEditMode={() => setEditMode(true)} onExitEditMode={() => { setEditMode(false); setSegments([]); }} editTool={editTool} setEditTool={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={handleApplyEdit} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleJSONAnalysis} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(id, temp) => handleGenerate(id, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} initialView={editMode ? { view: 'edit_area', ts: Date.now() } : null} currentEvolutionLevel={currentEvolutionLevel} />
