                                        }
                                    }}
                                    className={`p-2.5 rounded-xl transition-all ${activeAnnotationTool === at.id ? 'bg-indigo-600 text-white shadow-lg scale-105' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`}
                                    title={at.label}
