      <svg className={`absolute inset-0 pointer-events-none origin-top-left z-30 ${!isInteracting ? 'transition-transform duration-[600ms] cubic-bezier(0.2, 0.0, 0, 1)' : ''}`} style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})` }}>
          {snapLines.map((line, i) => ( 
            <line key={i} x1={line.x !== undefined ? line.x : -10000} y1={line.y !== undefined ? line.y : -10000} x2={line.x !== undefined ? line.x : 10000} y2={line.y !== undefined ? line.y : 10000} stroke="#3b82f6" strokeWidth={2/view.scale} strokeDasharray="6 6" /> 
          ))}
      </svg>
    </div>
