  const canvasRef = useRef<CanvasRef>(null);
  const chatRef = useRef<GeminiChatPanelRef>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const saveTimeoutRef = useRef<number | null>(null);

  const pasteCountRef = useRef(0);
  const lastPasteTimeRef = useRef(0);

  const selectedItem = selection.length === 1 ? items.find(it => it.id === selection[0]) || null : null;

  const findPlacementSpot = useCallback((width: number, height: number, itemsList: CanvasItem[], relativeTo?: CanvasItem, offsetIdx: number = 0) => {
    const spacing = 80; 
    if (itemsList.length === 0) { return { x: (window.innerWidth / 2 - view.x) / view.scale - width / 2, y: (window.innerHeight / 2 - view.y) / view.scale - height / 2 }; }
    const ref = relativeTo || itemsList[itemsList.length - 1];
    let startX = ref.x + ref.width + spacing;
    let startY = ref.y;
    const isOccupied = (tx: number, ty: number) => { return itemsList.some(it => { const overlapX = tx < it.x + it.width + 10 && tx + width + 10 > it.x; const overlapY = ty < it.y + it.height + 10 && ty + height + 10 > it.y; return overlapX && overlapY; }); };
    let curX = startX + (offsetIdx * (width / 4)); let curY = startY; let attempts = 0;
    while (isOccupied(curX, curY) && attempts < 50) { curX += spacing; attempts++; }
    if (attempts >= 50) { curX = ref.x; curY = ref.y + ref.height + spacing; attempts = 0; while (isOccupied(curX, curY) && attempts < 50) { curY += spacing; attempts++; } }
    return { x: curX, y: curY };
  }, [view.x, view.y, view.scale]);

  const centerOnItem = useCallback((item: CanvasItem, targetScale?: number) => {
    const scale = targetScale || Math.min(view.scale, 1.0);
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth;
    const centerX = leftPanelWidth + availableWidth / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (item.x + item.width / 2) * scale, y: centerY - (item.y + item.height / 2) * scale });
  }, [view.scale, showLayers, showHistory, isPropertiesPanelOpen]);

  const zoomToFit = useCallback(() => {
    if (items.length === 0) { setView({ x: 0, y: 0, scale: 1 }); return; }
    const minX = Math.min(...items.map(i => i.x));
    const minY = Math.min(...items.map(i => i.y));
    const maxX = Math.max(...items.map(i => i.x + i.width));
    const maxY = Math.max(...items.map(i => i.y + i.height));
    const contentWidth = maxX - minX; const contentHeight = maxY - minY;
    const padding = 100;
    const leftPanelWidth = (showLayers || showHistory) ? 224 + 80 : 80;
    const rightPanelWidth = isPropertiesPanelOpen ? 320 : 80;
    const availableWidth = window.innerWidth - leftPanelWidth - rightPanelWidth - padding * 2;
    const availableHeight = window.innerHeight - padding * 2;
    const scale = Math.min(availableWidth / contentWidth, availableHeight / contentHeight, 1.5);
    const centerX = leftPanelWidth + (window.innerWidth - leftPanelWidth - rightPanelWidth) / 2;
    const centerY = window.innerHeight / 2;
    setView({ scale, x: centerX - (minX + contentWidth / 2) * scale, y: centerY - (minY + contentHeight / 2) * scale });
  }, [items, showLayers, showHistory, isPropertiesPanelOpen]);

  const handleFile = useCallback(async (file: File, x?: number, y?: number) => {
    const reader = new FileReader();
    reader.onload = async (event) => {
        const content = event.target?.result as string;
        const isVideo = file.type.startsWith('video/') || file.name.endsWith('.webm');
        const { width, height } = isVideo ? await getVideoDimensions(content) : await getImageDimensions(content);
        const displayWidth = 500; const displayHeight = (height * displayWidth) / width;
        setItems(prev => {
            let targetPos;
            if (x !== undefined && y !== undefined) { targetPos = { x: (x - view.x) / view.scale - displayWidth / 2, y: (y - view.y) / view.scale - displayHeight / 2 }; }
            else { targetPos = findPlacementSpot(displayWidth, displayHeight, prev); }
            const newItem: CanvasItem = { id: crypto.randomUUID(), type: isVideo ? ItemType.VIDEO : ItemType.IMAGE, x: targetPos.x, y: targetPos.y, width: displayWidth, height: displayHeight, rotation: 0, content: content, status: 'generated', prompt: file.name, aspectRatio: getClosestAspectRatio(width, height) };
            setSelection([newItem.id]); return [...prev, newItem];
        });
    };
    reader.readAsDataURL(file);
  }, [view.x, view.y, view.scale, findPlacementSpot]);

  const handleCopy = useCallback((e: ClipboardEvent | null) => {
    if (e) { const target = e.target as HTMLElement; if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return; const selectionText = window.getSelection()?.toString(); if (selectionText && selectionText.length > 0) return; }
    if (selection.length === 0) return; const selectedItems = items.filter(it => selection.includes(it.id)); const data = JSON.stringify(selectedItems);
    if (e) e.clipboardData?.setData('application/json/recreate-items', data); localStorage.setItem('recreate_clipboard', data); if (e) e.preventDefault();
  }, [selection, items]);

  const handlePaste = useCallback(async (e: ClipboardEvent) => {
    const target = e.target as HTMLElement; const tagName = target.tagName?.toUpperCase();
    if (tagName === 'INPUT' || tagName === 'TEXTAREA' || target.isContentEditable) return;
    let dataStr = e.clipboardData?.getData('application/json/recreate-items');
    if (!dataStr) dataStr = localStorage.getItem('recreate_clipboard') || '';
    if (dataStr) { try { const itemsToPaste = JSON.parse(dataStr) as CanvasItem[]; if (itemsToPaste.length > 0) { e.preventDefault(); const now = Date.now(); if (now - lastPasteTimeRef.current > 2000) { pasteCountRef.current = 1; } else { pasteCountRef.current += 1; } lastPasteTimeRef.current = now; const offset = pasteCountRef.current * 24; const newItems = itemsToPaste.map(it => ({ ...it, id: crypto.randomUUID(), x: it.x + offset, y: it.y + offset, status: 'generated' as const })); setItems(prev => [...prev, ...newItems]); setSelection(newItems.map(it => it.id)); return; } } catch (err) {} }
    const clipboardItems = e.clipboardData?.items; if (!clipboardItems) return;
    for (let i = 0; i < clipboardItems.length; i++) { if (clipboardItems[i].type.indexOf("image") !== -1 || clipboardItems[i].type.indexOf("video") !== -1) { const file = clipboardItems[i].getAsFile(); if (file) { e.preventDefault(); handleFile(file); } } }
  }, [handleFile]);

  useEffect(() => {
    const handleDrop = (e: DragEvent) => { e.preventDefault(); const files = Array.from(e.dataTransfer?.files || []); files.forEach(file => { if (file.type.startsWith('image/') || file.type.startsWith('video/') || file.name.endsWith('.webm')) { handleFile(file, e.clientX, e.clientY); } }); };
    const handleDragOver = (e: DragEvent) => e.preventDefault();
    window.addEventListener('copy', handleCopy as any); window.addEventListener('paste', handlePaste); window.addEventListener('drop', handleDrop); window.addEventListener('dragover', handleDragOver);
    return () => { window.removeEventListener('copy', handleCopy as any); window.removeEventListener('paste', handlePaste); window.removeEventListener('drop', handleDrop); window.removeEventListener('dragover', handleDragOver); };
  }, [handleCopy, handlePaste, handleFile]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement; if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;
      if (e.key === 'Delete' || e.key === 'Backspace') { if (selection.length > 0) handleDeleteItems(selection); }
      if (e.key === ' ') { e.preventDefault(); if (quickLookItem) setQuickLookItem(null); else if (selectedItem) setQuickLookItem(selectedItem); }
      if (e.key === 'Escape') { setQuickLookItem(null); if (editMode) setEditMode(false); if (isPickingPoint) setIsPickingPoint(false); setExpressionState({ itemId: '', isOpen: false }); setInferenceState({ itemId: '', isOpen: false }); setTool('select'); }
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.preventDefault();
        if (quickLookItem) {
            const assetItems = items.filter(it => (it.type === ItemType.IMAGE || it.type === ItemType.VIDEO) && it.content);
            if (assetItems.length > 0) { const currentIndex = assetItems.findIndex(it => it.id === quickLookItem.id); let nextIndex = currentIndex; if (e.key === 'ArrowRight' || e.key === 'ArrowDown') nextIndex = (currentIndex + 1) % assetItems.length; else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') nextIndex = (currentIndex - 1 + assetItems.length) % assetItems.length; const nextItem = assetItems[nextIndex]; setQuickLookItem(nextItem); setSelection([nextItem.id]); centerOnItem(nextItem); }
        } else if (selection.length > 0) {
            const step = e.shiftKey ? 10 : 1;
            const updates = selection.map(id => { const item = items.find(i => i.id === id); if (!item) return null; let nx = item.x, ny = item.y; if (e.key === 'ArrowUp') ny -= step; if (e.key === 'ArrowDown') ny += step; if (e.key === 'ArrowLeft') nx -= step; if (e.key === 'ArrowRight') nx += step; return { id, updates: { x: nx, y: ny } }; }).filter(Boolean) as { id: string, updates: Partial<CanvasItem> }[];
            if (updates.length > 0) handleUpdateItems(updates);
        }
      }
      if (e.key.toLowerCase() === 'v') setTool('select');
      if (e.key.toLowerCase() === 'h') setTool('hand');
      if (e.key.toLowerCase() === 'r') setTool('point');
      if (e.key.toLowerCase() === 'c') setTool('capture');
      if (e.key.toLowerCase() === 'g') setShowGrid(prev => !prev);
    };
    window.addEventListener('keydown', handleKeyDown); return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selection, items, selectedItem, quickLookItem, editMode, view.scale, showLayers, showHistory, centerOnItem, isPickingPoint]);

  const startRecording = async (resolution: string) => {
    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ video: { cursor: "always" } as any, audio: false }); streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream); mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.ondataavailable = (event) => { if (event.data.size > 0) recordedChunksRef.current.push(event.data); };
      mediaRecorder.onstop = () => { const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `Recraft-${new Date().getTime()}.webm`; a.click(); setRecordingStatus('idle'); setRecordingTime(0); if (timerRef.current) window.clearInterval(timerRef.current); };
      mediaRecorder.start(); setRecordingStatus('recording'); timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch (err) {}
  };
  const stopRecording = () => { mediaRecorderRef.current?.stop(); streamRef.current?.getTracks().forEach(track => track.stop()); };

  useEffect(() => { const initLoad = async () => { const snapshots = await getAllSnapshots(); if (snapshots.length > 0) setItems(snapshots[0].items); const recipes = await getAllRecipes(); setAvailableRecipes(recipes); }; initLoad(); }, []);
  useEffect(() => {
    if (items.length === 0) return;
    if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
    saveTimeoutRef.current = window.setTimeout(async () => {
      const lastAsset = [...items].reverse().find(i => (i.type === ItemType.IMAGE || i.type === ItemType.VIDEO) && i.content);
      const snapshot: ProjectSnapshot = { id: crypto.randomUUID(), name: lastAsset?.prompt?.slice(0, 30) || 'Snapshot', items, thumbnail: (lastAsset?.type === ItemType.IMAGE ? lastAsset.content : ''), updatedAt: Date.now() }; await saveSnapshot(snapshot);
    }, 2000);
  }, [items]);

  const handleAddToCanvas = async (base64: string, promptText?: string, refId?: string) => {
    const { width, height } = await getImageDimensions(base64);
    let displayWidth = 512; let referenceId: string | null = refId || (selection.length === 1 ? selection[0] : (items.length > 0 ? items[items.length - 1].id : null));
    setItems(currentItems => {
        const actualReferenceItem = referenceId ? currentItems.find(i => i.id === referenceId) : undefined;
        let targetDisplayHeight = (height * displayWidth) / width;
        if (actualReferenceItem) { const refRatio = actualReferenceItem.width / actualReferenceItem.height; const newRatio = width / height; displayWidth = actualReferenceItem.width; if (Math.abs(refRatio - newRatio) < 0.2) { targetDisplayHeight = actualReferenceItem.height; displayWidth = (width * targetDisplayHeight) / height; } else { targetDisplayHeight = (height * displayWidth) / width; } }
        const spot = findPlacementSpot(displayWidth, targetDisplayHeight, currentItems, actualReferenceItem);
        const newItem: CanvasItem = { id: crypto.randomUUID(), type: ItemType.IMAGE, x: spot.x, y: spot.y, width: displayWidth, height: targetDisplayHeight, rotation: 0, content: base64, status: 'generated', prompt: promptText || 'AI Created', aspectRatio: getClosestAspectRatio(width, height) };
        setSelection([newItem.id]); setTimeout(() => centerOnItem(newItem, 0.8), 50); return [...currentItems, newItem];
    });
  };

  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item)), []);
  const handleUpdateItems = useCallback((updates: { id: string, updates: Partial<CanvasItem> }[]) => setItems(prev => { const newItems = [...prev]; updates.forEach(({ id, updates: itemUpdates }) => { const idx = newItems.findIndex(i => id === id); if (idx !== -1) newItems[idx] = { ...newItems[idx], ...itemUpdates }; }); return newItems; }), []);
  const handleDeleteItems = useCallback((ids: string[]) => { setItems(prev => prev.filter(item => !ids.includes(item.id))); setSelection([]); }, []);

  const handleGenerate = async (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>, existingItem?: CanvasItem, manualRefs?: string[]) => {
    const rawPrompt = overridePrompt || (items.find(i => i.id === id)?.prompt || "Professional design");
    const isEvolution = rawPrompt.startsWith('__EVOLUTION__');

    let promptsToProcess: string[] = []; let inferenceCfgs: InferenceSettings[] = [];
    const isInference = rawPrompt.startsWith('inference:');
    if (isInference) {
        const [_, data] = rawPrompt.split(':'); const [p, inf, countStr, recipeId, subType] = data.split('|');
        if (p === '__VISUAL_PEEL__') { handleVisualPeelAction(id); return; }
        const influence = parseFloat(inf); const count = parseInt(countStr) || 1; const subjectType = subType || 'industrial';
        if (count > 1) { inferenceCfgs = [ { prompt: p, influence: 0.95, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any }, { prompt: p, influence: 0.75, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any }, { prompt: p, influence: 0.55, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any }, ]; promptsToProcess = inferenceCfgs.map(s => s.prompt); }
        else { inferenceCfgs = [{ prompt: p, influence, style: STYLES[1].promptSuffix, recipeId: recipeId || settings?.recipeId, subjectType: subjectType as any }]; promptsToProcess = [p]; }
    } else {
        const separationKeywords = ["分别", "各自", "each", "separately"];
        const hasSeparationIntent = separationKeywords.some(kw => rawPrompt.includes(kw));
        if (hasSeparationIntent) { let cleanPrompt = rawPrompt.replace(/^(?:我想|请|能不能|帮我|能否)?(?:分别生成|分别设计|分别|生成|设计|各自生成|各自设计|each|separately generate|generate separately)\s*/i, ''); const subjects = cleanPrompt.split(/(?:\s*[，、,]\s*|\s+和\s+|\s+以及\s+|\s+与\s+|\s+与及\s+|\s+plus\s+|\s+and\s+|\s+&\s+)/i).map(s => s.trim()).filter(s => s.length > 0); if (subjects.length > 1) promptsToProcess = subjects; else promptsToProcess = [rawPrompt]; }
        else { promptsToProcess = [rawPrompt]; }
    }
    const sourceItem = items.find(i => i.id === id); const contextItem = sourceItem || (selection.length === 1 ? items.find(it => it.id === selection[0]) : null);
    let targetW = 512; let targetH = 512; let ratioToUse = settings?.ratio || '1:1';
    if (existingItem) { targetW = existingItem.width; targetH = existingItem.height; }
    else if (manualRefs && manualRefs.length > 0) { const dims = await getImageDimensions(manualRefs[0]); targetW = dims.width; targetH = dims.height; ratioToUse = getClosestAspectRatio(dims.width, dims.height); }
    else if (contextItem) { targetW = contextItem.width; targetH = contextItem.height; ratioToUse = contextItem.aspectRatio || getClosestAspectRatio(targetW, targetH); }
    else { const ratioObj = ASPECT_RATIOS.find(r => r.id === ratioToUse) || ASPECT_RATIOS[0]; targetW = ratioObj.width; targetH = ratioObj.height; }
    const styleId = settings?.style || 'industrial'; const styleObj = STYLES.find(s => s.id === styleId) || STYLES[1];
    let currentTempItems = [...items]; const tasks: { nid: string, prompt: string, infCfg?: InferenceSettings }[] = [];
    promptsToProcess.forEach((promptText, idx) => {
        const nid = crypto.randomUUID(); const spot = findPlacementSpot(targetW, targetH, currentTempItems, contextItem, idx);
        let finalPrompt = promptText;
        if (isEvolution && contextItem) {
            const parts = rawPrompt.split('|');
            const level = parseInt(parts[1]);
            const isCnc = parts.length > 2 && parts[2] === 'CNC';
            if (!isNaN(level)) setCurrentEvolutionLevel(level);
            finalPrompt = getEvolutionDirective(level, contextItem.prompt || "industrial design", isCnc);
        }
        const infCfg = inferenceCfgs[idx] || undefined;
        const newItem: CanvasItem = { id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: targetW, height: targetH, rotation: (existingItem || contextItem)?.rotation || 0, content: '', status: 'loading', prompt: finalPrompt, aspectRatio: ratioToUse, links: contextItem ? [contextItem.id] : [], spatialConfig: settings?.spatialConfig, inferenceInfluence: infCfg?.influence };
        currentTempItems.push(newItem); tasks.push({ nid, prompt: finalPrompt, infCfg });
    });
    setItems(currentTempItems); setSelection(tasks.map(t => t.nid));
    tasks.forEach(async ({ nid, prompt: promptToUse, infCfg }) => {
        try {
            let recipeTxt = ""; const currentRecipeId = infCfg?.recipeId || settings?.recipeId;
            if (currentRecipeId) { const recipe = availableRecipes.find(r => r.id === currentRecipeId); if (recipe) recipeTxt = recipe.instruction; }
            let url: string;
            if (infCfg && contextItem && contextItem.content) { url = await generateWithReferences(promptToUse, [{ label: 'Source Volume', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig || contextItem.spatialConfig, recipeTxt, infCfg); }
            else if (isEvolution && contextItem && contextItem.content) { url = await generateWithReferences(promptToUse, [{ label: 'Evolution Source', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig || contextItem.spatialConfig, recipeTxt); }
            else if (manualRefs && manualRefs.length > 0) { const refs = manualRefs.map((r, idx) => ({ label: `Ref ${idx}`, base64: r })); url = await generateWithReferences(promptToUse, refs, ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig, recipeTxt); }
            else if (contextItem && contextItem.content) { url = await generateWithReferences(promptToUse, [{ label: 'Source', base64: contextItem.content }], ratioToUse, styleObj.promptSuffix, 1.0, settings?.resolution || '1K', settings?.spatialConfig || contextItem.spatialConfig, recipeTxt); }
            else { url = await generateImage(promptToUse, styleObj.promptSuffix, ratioToUse, 1.0, settings?.resolution || '1K', settings?.spatialConfig, recipeTxt); }
            const { width, height } = await getImageDimensions(url); setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated', height: (height * i.width) / width, aspectRatio: getClosestAspectRatio(width, height) } : i));
        } catch (e: any) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
    });
  };

  const handleApplyEdit = async (prompt: string) => {
    if (!selectedItem || !canvasRef.current) return;
    const maskData = await canvasRef.current.getMaskData(); if (!maskData) return;
    const nid = crypto.randomUUID(); const spot = findPlacementSpot(selectedItem.width, selectedItem.height, items, selectedItem);
    setItems(prev => [...prev, { id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: selectedItem.width, height: selectedItem.height, rotation: selectedItem.rotation, content: '', status: 'loading', prompt, aspectRatio: selectedItem.aspectRatio || '1:1', links: [selectedItem.id] }]);
    setSelection([nid]); setEditMode(false); setSegments([]);
    try { const url = await editImage(selectedItem.content, prompt, selectedItem.aspectRatio || '1:1', maskData.mask); const { width, height } = await getImageDimensions(url); setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated', height: (height * i.width) / width } : i)); } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
  };

  const handleJSONAnalysis = async (id: string) => {
    const item = items.find(i => i.id === id); if (!item || !item.content) return;
    setIsAnalyzingJSON(true); try { const result = await detectImageJSONSegments(item.content); setSegments(result.segments || []); }
    catch (e) {} finally { setIsAnalyzingJSON(false); }
  };

  const handlePickPoint = async (itemId: string, y: number, x: number) => {
      const item = items.find(i => i.id === itemId); if (!item || !item.content) return;
      if (tool === 'point') { setItems(prev => { const nextLabel = (prev.reduce((max, it) => Math.max(max, ...(it.identifiedPoints?.map(p => parseInt(p.label, 10)) || [0])), 0) + 1).toString(); const newPoint: IdentifiedPoint = { id: crypto.randomUUID(), y, x, label: nextLabel }; chatRef.current?.addPointReference(itemId, item.content || '', nextLabel, [y, x]); return prev.map(it => it.id === itemId ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), newPoint] } : it); }); return; }
      try { const aiLabel = await identifyPoint(item.content, y, x); setItems(prev => { const nextLabel = (prev.reduce((max, it) => Math.max(max, ...(it.identifiedPoints?.map(p => parseInt(p.label, 10)) || [0])), 0) + 1).toString(); const newPoint: IdentifiedPoint = { id: crypto.randomUUID(), y, x, label: nextLabel, description: aiLabel }; chatRef.current?.addPointReference(itemId, item.content || '', nextLabel, [y, x]); return prev.map(it => it.id === itemId ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), newPoint] } : it); }); } catch (e) {}
  };

  const handleVisualPeelAction = async (itemId: string) => {
    const item = items.find(i => i.id === itemId); if (!item || !item.content) return;
    const nid = crypto.randomUUID(); const spot = findPlacementSpot(item.width, item.height, items, item);
    setItems(prev => [...prev, { id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: item.width, height: item.height, rotation: item.rotation, content: '', status: 'loading', prompt: 'Visual De-shell Prototype', aspectRatio: item.aspectRatio || '1:1', links: [item.id] }]);
    setSelection([nid]); try { const essence = await extractSubjectEssence(item.content); const peeledUrl = await generateVisualPeel(item.content, essence, item.aspectRatio || '1:1'); const { width, height } = await getImageDimensions(peeledUrl); setItems(prev => prev.map(i => i.id === nid ? { ...i, content: peeledUrl, status: 'generated', essence: essence, height: (height * i.width) / width } : i)); } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
  };

  const handleFloatingAction = async (id: string, action: string) => {
    const selectedItems = items.filter(i => selection.includes(i.id)); const firstItem = selectedItems[0]; if (!firstItem) return;
    if (action.startsWith('expr:')) { handleGenerate(firstItem.id, `Change to ${action.split(':')[1]}`); return; }
    if (action.startsWith('inference:')) { handleGenerate(firstItem.id, `inference:${action.split(':')[1]}`); return; }
    if (action.startsWith('evolve_with_level:')) { setCurrentEvolutionLevel(parseInt(action.split(':')[1])); handleGenerate(firstItem.id, `__EVOLUTION__|${action.split(':')[1]}`); return; }
    switch(action) {
      case 'visual_peel': handleVisualPeelAction(firstItem.id); break;
      case 'evolve': 
        setIsPropertiesPanelOpen(true);
        setPropertiesInitialView({ view: 'evolution', ts: Date.now() });
        break;
      case 'expression': setExpressionState({ itemId: firstItem.id, isOpen: true }); break;
      case 'inference': setInferenceState({ itemId: firstItem.id, isOpen: true }); break;
      case 'variation': handleGenerate(firstItem.id, 'Generate variation'); break;
      case 'remove_bg': handleGenerate(firstItem.id, 'Remove background'); break;
      case 'upscale': handleGenerate(firstItem.id, 'Upscale'); break;
      case 'edit': setEditMode(true); setIsPropertiesPanelOpen(true); break;
      case 'delete': handleDeleteItems(selection); break;
      case 'copy': handleCopy(null); break;
      case 'extract_recipe': setIsExtractingRecipe(true); try { const imgs = selectedItems.filter(it => it.content).map(it => it.content!); const instruction = await extractDesignRecipe(imgs, 0); setExtractedRecipe({ instruction, images: imgs }); } catch (e) {} finally { setIsExtractingRecipe(false); } break;
    }
  };

  const handleCaptureRegion = useCallback(async (region: Rect, action: 'chat' | 'canvas', annotations: any[] = []) => {
      const scale = 2; const canvas = document.createElement('canvas'); canvas.width = region.width * scale; canvas.height = region.height * scale; const ctx = canvas.getContext('2d'); if (!ctx) return;
      ctx.scale(scale, scale); ctx.translate(-region.x, -region.y);
      for (const item of items) { const intersects = !(item.x > region.x + region.width || item.x + item.width < region.x || item.y > region.y + region.height || item.y + item.height < region.y); if (intersects && item.content) { if (item.type === ItemType.IMAGE) { const img = new Image(); img.src = item.content; await new Promise(resolve => { img.onload = () => { ctx.save(); ctx.translate(item.x + item.width/2, item.y + item.height/2); ctx.rotate((item.rotation || 0) * Math.PI / 180); ctx.drawImage(img, -item.width/2, -item.height/2, item.width, item.height); ctx.restore(); resolve(null); }; img.onerror = () => resolve(null); }); } } }
      const base64 = canvas.toDataURL('image/png'); if (action === 'chat') { chatRef.current?.addExternalAttachment(crypto.randomUUID(), base64); setTool('select'); } else { handleAddToCanvas(base64, "Region Capture"); setTool('select'); }
  }, [items]);

  const handleSyncPointsToGemini = (id: string) => { const item = items.find(i => i.id === id); if (item && item.content && chatRef.current) { const points = item.identifiedPoints?.map(p => ({ label: p.label, point: [p.y, p.x] as [number, number] })) || []; chatRef.current.addBulkPointReferences(item.id, item.content, points); } };
  const handleToggleFit = () => { if (selection.length === 1) { const item = items.find(i => i.id === selection[0]); if (item) centerOnItem(item); } else { zoomToFit(); } };

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative">
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => { const spot = findPlacementSpot(800, 600, items); const f: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: spot.x, y: spot.y, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' }; setItems(p => [...p, f]); setSelection([f.id]); }} recordingStatus={recordingStatus} onStartRecording={startRecording} onStopRecording={stopRecording} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={recordingTime} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection.length > 0 ? selection[0] : null} onSelectItem={(id) => { setSelection([id]); const item = items.find(i => i.id === id); if (item) centerOnItem(item); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => setItems(snap.items)} />
      <div className="w-full h-full">
        <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={it => setItems(p => [...p, it])} updateItem={handleUpdateItem} updateItems={handleUpdateItems} onContextMenu={(e, id) => { if (tool === 'point' || tool === 'capture') { setTool('select'); return; } setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId: id }); }} onDelete={id => handleDeleteItems([id])} editMode={editMode} editTool={editTool} brushSize={brushSize} brushColor={brushColor} segments={segments} onApplyEdit={handleApplyEdit} onSelectItem={(id) => { const item = items.find(it => id === it.id); if (item && (item.type === ItemType.IMAGE || item.type === ItemType.VIDEO) && item.content) { if (isPickingPoint && pickingTargetId === item.id) return; if (tool === 'point' || tool === 'capture') return; setQuickLookItem(item); } }} onPointPicked={handlePickPoint} isPickingPoint={isPickingPoint && !!pickingTargetId} onPointTagClick={(it, pt) => chatRef.current?.addPointReference(it.id, it.content || '', pt.label, [pt.y, pt.x])} showPointLabels={showPointLabels} onDeletePoint={(iid, pid) => setItems(prev => prev.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it))} onDeletePointLocal={(iid, pid) => setItems(prev => prev.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it))} onMovePoint={(iid, pid, ny, nx) => setItems(prev => prev.map(item => item.id === iid ? { ...item, identifiedPoints: item.identifiedPoints?.map(p => p.id === pid ? { ...p, y: ny, x: nx } : p) } : item))} onMovePointEnd={(iid, pid, from, to) => { const item = items.find(i => i.id === iid); if (item?.content) { const point = item.identifiedPoints?.find(p => p.id === pid); if (point) chatRef.current?.appendMovementDescription(iid, item.content, point.label, from, to); } }} isTextMode={editSubMode === 'text'} showGrid={showGrid} onZoomToFit={zoomToFit} onCaptureRegion={handleCaptureRegion} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} currentEvolutionLevel={currentEvolutionLevel} />
      </div>
      {editMode && ( <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[100] flex flex-col items-center gap-4 pointer-events-none animate-in fade-in slide-in-from-bottom-8 duration-500"> <div className="bg-[#18181b] p-2 rounded-full shadow-2xl flex items-center gap-4 border border-white/5 pointer-events-auto"> {[{id:'red',v:'#ef4444'},{id:'yellow',v:'#facc15'},{id:'green',v:'#22c55e'},{id:'blue',v:'#3b82f6'},{id:'white',v:'#ffffff'}].map(c => ( <button key={c.id} onClick={() => setBrushColor(c.v)} className={`w-8 h-8 rounded-full border-2 transition-all hover:scale-110 active:scale-90 ${brushColor === c.v ? 'border-indigo-500 ring-4 ring-indigo-500/20' : 'border-transparent opacity-80'}`} style={{ backgroundColor: c.v }} /> ))} </div> <div className="bg-[#18181b] p-1.5 rounded-full shadow-2xl flex items-center gap-1 border border-white/5 pointer-events-auto"> <button onClick={() => setEditSubMode('paint')} className={`w-14 h-10 flex items-center justify-center rounded-full transition-all ${editSubMode === 'paint' ? 'bg-[#27272a] text-indigo-400 shadow-inner' : 'text-zinc-500 hover:text-zinc-300'}`}><VectorIcon className="w-5 h-5" /></button> <button onClick={() => { setEditSubMode('text'); setIsPropertiesPanelOpen(true); }} className={`w-14 h-10 flex items-center justify-center rounded-full transition-all ${editSubMode === 'text' ? 'bg-[#27272a] text-indigo-400 shadow-inner' : 'text-zinc-500 hover:text-zinc-300'}`}><TypeIcon className="w-5 h-5" /></button> </div> </div> )}
      <div className={`fixed right-4 top-4 bottom-4 flex flex-col items-end transition-all duration-500 ease-in-out z-40 ${isPropertiesPanelOpen ? 'w-80' : 'w-16'}`}>
        {!isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(true)} className="w-14 h-14 rounded-full flex items-center justify-center transition-all shadow-2xl border bg-[#09090b] border-zinc-800 text-indigo-400 hover:scale-110"><SlidersIcon className="w-6 h-6" /></button>}
        <div className={`flex-1 w-full overflow-hidden transition-all duration-500 origin-right ${isPropertiesPanelOpen ? 'scale-100 opacity-100' : 'scale-90 opacity-0 pointer-events-none'}`}>
           <div className="relative h-full">
             {isPropertiesPanelOpen && <button onClick={() => setIsPropertiesPanelOpen(false)} className="absolute top-4 right-4 z-[50] w-9 h-9 rounded-xl flex items-center justify-center bg-white/10 hover:bg-white/20 text-white transition-all border border-white/10 shadow-lg"><XIcon className="w-4 h-4" /></button>}
             <PropertiesPanel selectedItem={selectedItem} onUpdateItem={handleUpdateItem} onGenerate={handleGenerate} onDelete={id => handleDeleteItems([id])} onAutoPrompt={id => analyzeImageForPrompt(items.find(it => it.id === id)?.content || '').then(p => handleUpdateItem(id, { prompt: p }))} onSendToPrompt={id => { const item = items.find(i => i.id === id); if (item?.content) setExternalRefImage(item.content); }} onSendToGemini={id => { const item = items.find(i => i.id === id); if (item?.content) chatRef.current?.addExternalAttachment(item.id, item.content); }} onSyncPointsToGemini={handleSyncPointsToGemini} onEnterEditMode={() => setEditMode(true)} onExitEditMode={() => { setEditMode(false); setSegments([]); }} editTool={editTool} setEditTool={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={handleApplyEdit} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleJSONAnalysis} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(id, temp) => handleGenerate(id, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} initialView={propertiesInitialView || (editMode ? { view: 'edit_area', ts: Date.now() } : null)} currentEvolutionLevel={currentEvolutionLevel} />
           </div>
        </div>
      </div>
      {contextMenu && <ContextMenu x={contextMenu.x} y={contextMenu.y} selectedItem={items.find(i => i.id === contextMenu.itemId) || null} onSelect={action => { if (action === 'delete') handleDeleteItems(selection); if (action === 'copy') { handleCopy(null); } if (action === 'send_to_gemini') { const item = items.find(i => i.id === contextMenu.itemId); if (item?.content) chatRef.current?.addExternalAttachment(item.id, item.content); } setContextMenu(null); }} onClose={() => setContextMenu(null)} isMulti={selection.length > 1} />}
      {quickLookItem && <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/95 backdrop-blur-2xl animate-in fade-in duration-300" onClick={() => setQuickLookItem(null)}> <div className="absolute top-8 right-8"> <button onClick={() => setQuickLookItem(null)} className="w-12 h-12 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition-all border border-white/10 shadow-2xl"> <XIcon className="w-6 h-6" /> </button> </div> <div className="relative max-w-[90vw] max-h-[90vh] flex flex-col items-center gap-6 animate-in zoom-in-95 duration-300" onClick={e => e.stopPropagation()}> {quickLookItem.type === ItemType.IMAGE ? <img src={quickLookItem.content} className="max-w-full max-h-[80vh] rounded-3xl shadow-[0_40px_100px_rgba(0,0,0,0.8)] border border-white/10" alt="Quick Look" /> : <video src={quickLookItem.content} controls className="max-w-full max-h-[80vh] rounded-3xl" />} <div className="bg-zinc-900/80 backdrop-blur-md px-8 py-5 rounded-3xl border border-zinc-800 flex flex-col gap-1 items-center shadow-2xl"> <span className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em]">Prompt Content</span> <p className="text-white text-[14px] font-medium max-w-lg text-center leading-relaxed"> {quickLookItem.prompt || "Asset"} </p> </div> </div> </div>}
      <div className="absolute bottom-8 left-8 flex items-center gap-1 z-50 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-md border border-zinc-200 dark:border-zinc-800 rounded-lg p-0.5 shadow-2xl"> <button onClick={() => setView(v => ({...v, scale: Math.max(0.1, v.scale - 0.1)}))} className="w-6 h-6 rounded-md flex items-center justify-center text-zinc-500 hover:bg-zinc-100 transition-colors"><MinusIcon className="w-3.5 h-3.5" /></button> <span className="px-0.5 text-[9px] font-black text-zinc-600 w-10 text-center select-none font-mono">{Math.round(view.scale * 100)}%</span> <button onClick={() => setView(v => ({...v, scale: Math.min(5, v.scale + 0.1)}))} className="w-6 h-6 rounded-md flex items-center justify-center text-zinc-500 hover:bg-zinc-100 transition-colors"><PlusIcon className="w-3.5 h-3.5" /></button> <div className="w-px h-3 bg-zinc-200 mx-0.5" /> <button onClick={handleToggleFit} className={`w-6 h-6 rounded-md flex items-center justify-center transition-colors ${selection.length > 0 ? 'text-indigo-600' : 'text-zinc-500'} hover:bg-zinc-100`}> <FocusIcon className="w-3.5 h-3.5" /> </button> <div className="w-px h-3 bg-zinc-200 mx-0.5" /> <button onClick={() => setShowGrid(!showGrid)} className={`w-6 h-6 rounded-md flex items-center justify-center transition-colors ${showGrid ? 'text-indigo-600' : 'text-zinc-400'} hover:bg-zinc-100`} title="Toggle Grid (G)"> <LayoutGridIcon className="w-3.5 h-3.5" /> </button> <button onClick={() => setShowPointLabels(!showPointLabels)} className={`w-6 h-6 rounded-md flex items-center justify-center transition-colors ${showPointLabels ? 'text-indigo-600' : 'text-zinc-400'} hover:bg-zinc-100`} title="Toggle Feature Descriptions"> {showPointLabels ? <EyeIcon className="w-3.5 h-3.5" /> : <EyeOffIcon className="w-3.5 h-3.5" />} </button> </div>
      <div className={`fixed left-1/2 -translate-x-1/2 transition-all duration-500 ease-in-out z-50 flex flex-col items-center ${isBottomBarOpen ? 'bottom-8 w-full max-w-[640px]' : 'bottom-4 w-14'}`}> <div className={`w-full transition-all duration-500 origin-bottom ${isBottomBarOpen ? 'scale-100 opacity-100 mb-3' : 'scale-0 opacity-0 h-0 pointer-events-none'}`}> <BottomBar lastGenerated={items.length > 0 ? items[items.length - 1].content || null : null} externalRef={externalRefImage} onExternalRefConsumed={() => setExternalRefImage(null)} onGenerate={(p, s, r, refs, c, l, res, recipeId) => handleGenerate('', p, { style: s, ratio: r, imageCount: c, artisticLevel: l, resolution: res, recipeId }, undefined, refs)} onClose={() => setIsBottomBarOpen(false)} /> </div> {!isBottomBarOpen && <button onClick={() => setIsBottomBarOpen(true)} className="w-12 h-12 rounded-full flex items-center justify-center shadow-2xl transition-all border bg-[#09090b] border-zinc-800 text-white hover:scale-110 group"><SparklesIcon className="w-6 h-6 text-indigo-400 group-hover:rotate-12 transition-transform" /></button>} </div>
      {extractedRecipe && ( <DesignRecipePanel initialInstruction={extractedRecipe.instruction} exampleImages={extractedRecipe.images} onSave={async (name, final) => { setIsSavingRecipe(true); try { const recipe: DesignRecipe = { id: crypto.randomUUID(), name, instruction: final, exampleImages: extractedRecipe.images.slice(0, 3), createdAt: Date.now() }; await saveRecipe(recipe); setAvailableRecipes(await getAllRecipes()); setExtractedRecipe(null); } finally { setIsSavingRecipe(false); } }} onClose={() => setExtractedRecipe(null)} isSaving={isSavingRecipe} /> )}
      {isExtractingRecipe && ( <div className="fixed inset-0 z-[500] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center gap-8 animate-in fade-in duration-500"> <div className="relative w-24 h-24 flex items-center justify-center"> <div className="ai-ring" style={{ animationDelay: '0s', width: '100%', height: '100%' }} /> <div className="ai-ring" style={{ animationDelay: '0.5s', width: '130%', height: '130%' }} /> <FlaskIcon className="w-10 h-10 text-indigo-400 relative z-10 animate-pulse" /> </div> <div className="text-center space-y-2"> <h3 className="text-white font-black text-sm uppercase tracking-[0.4em]">正在破译设计基因</h3> <p className="text-zinc-400 text-[10px] font-bold uppercase tracking-widest">GEMINI IS EXTRACTING AESTHETIC GENES...</p> </div> </div> )}
      <GeminiChatPanel ref={chatRef} onAddToCanvas={handleAddToCanvas} onReceiveSegments={(segs) => { setSegments(segs); setEditMode(true); }} />
      <input type="file" ref={fileInputRef} onChange={(e) => { const files = Array.from(e.target.files || []) as File[]; files.forEach(file => handleFile(file)); }} multiple className="hidden" accept="image/*,video/*,.webm" />
    </div>
  );
};

export default App;
